        async function geocodeAddressNominatim(address) {
            if (!address) return null;

            let emailParam = '';
            // Tenta obter o e-mail de identificação dos metadados
            if (embeddedData && embeddedData.metadata && Array.isArray(embeddedData.metadata)) {
                const emailMeta = embeddedData.metadata.find(m => m.key === 'BREVO_SENDER_EMAIL');
                if (emailMeta && emailMeta.value) {
                    emailParam = `&email=${encodeURIComponent(emailMeta.value)}`;
                }
            }

            const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(address)}&limit=1${emailParam}`;

            try {
                const response = await fetch(url, {
                    headers: { 'User-Agent': 'PrimeDashboardApp/1.0' }
                });


                if (!response.ok) return null;
                const data = await response.json();
                if (data && data.length > 0) {
                    return {
                        lat: parseFloat(data[0].lat),
                        lng: parseFloat(data[0].lon),
                        formatted_address: data[0].display_name
                    };
                }
            } catch (e) {
                console.warn("Nominatim fetch failed:", e);
            }
            return null;
        }

        async function updateCityMap() {
            const cityMapContainer = document.getElementById('city-map-container');
            if (!leafletMap || (cityMapContainer && cityMapContainer.classList.contains('hidden'))) return;

            const { clients, sales } = getCityFilteredData();
            if (!clients || clients.length === 0) return;

            const jobId = ++cityMapJobId;
            isCityMapCalculating = true;

            // Cache for Async Marker Generation
            currentFilteredClients = clients;
            areMarkersGenerated = false;
            if (clientMarkersLayer) clientMarkersLayer.clearLayers();

            const heatData = [];
            const missingCoordsClients = [];
            const validBounds = [];

            // Heatmap Loop (Sync - Fast) - Update UI immediately
            clients.forEach(client => {
                const codCli = normalizeKey(String(client['Código'] || client['codigo_cliente']));
                const coords = clientCoordinatesMap.get(codCli);

                if (coords) {
                    heatData.push([coords.lat, coords.lng, 1.0]);
                    validBounds.push([coords.lat, coords.lng]);
                } else {
                    missingCoordsClients.push(client);
                }
            });

            // Update Heatmap
            if (heatLayer) {
                // Fix: Check if layer is active on map to avoid "Cannot read properties of null (reading '_animating')"
                if (leafletMap && leafletMap.hasLayer(heatLayer)) {
                    heatLayer.setLatLngs(heatData);
                } else {
                    // Update data source even if hidden to keep it in sync
                    heatLayer._latlngs = heatData;
                }
            }

            // Fit Bounds
            if (validBounds.length > 0) {
                leafletMap.fitBounds(validBounds);
            }

            // Sales Aggregation (Async Chunked)
            const tempSalesMap = new Map();
            const tempMixStatus = new Map();

            if (sales) {
                runAsyncChunked(sales, (s) => {
                    const cod = s.CODCLI;
                    const val = Number(s.VLVENDA) || 0;
                    tempSalesMap.set(cod, (tempSalesMap.get(cod) || 0) + val);

                    // Mix Logic
                    let mix = tempMixStatus.get(cod);
                    if (!mix) {
                        mix = { elma: false, foods: false };
                        tempMixStatus.set(cod, mix);
                    }

                    const codFor = String(s.CODFOR);
                    // Elma: 707, 708, 752
                    if (window.isElma(codFor)) {
                        mix.elma = true;
                    }
                    // Foods: 1119
                    else if (window.isFoods(codFor)) {
                        mix.foods = true;
                    }
                }, () => {
                    // On Complete
                    if (jobId !== cityMapJobId) return; // Cancelled by newer request

                    currentFilteredSalesMap = tempSalesMap;
                    currentClientMixStatus = tempMixStatus;
                    areMarkersGenerated = false;
                    isCityMapCalculating = false;

                    // Trigger Marker Logic (Now that data is ready)
                    updateMarkersVisibility();

                }, () => jobId !== cityMapJobId); // isCancelled check
            } else {
                // No sales, clear maps
                if (jobId === cityMapJobId) {
                    currentFilteredSalesMap = new Map();
                    currentClientMixStatus = new Map();
                    areMarkersGenerated = false;
                    isCityMapCalculating = false;
                    updateMarkersVisibility();
                }
            }
        }

        function updateMarkersVisibility() {
            if (!leafletMap || !clientMarkersLayer) return;
            const zoom = leafletMap.getZoom();

            if (zoom >= 14) {
                if (!areMarkersGenerated) {
                    generateMarkersAsync();
                } else {
                    if (!leafletMap.hasLayer(clientMarkersLayer)) leafletMap.addLayer(clientMarkersLayer);
                }
            } else {
                if (leafletMap.hasLayer(clientMarkersLayer)) leafletMap.removeLayer(clientMarkersLayer);
            }
        }

        function generateMarkersAsync() {
            if (areMarkersGenerated || isCityMapCalculating) return;

            // Use local reference to avoid race conditions if filter changes mid-process
            const clientsToProcess = currentFilteredClients;

            runAsyncChunked(clientsToProcess, (client) => {
                const codCli = normalizeKey(String(client['Código'] || client['codigo_cliente']));
                const coords = clientCoordinatesMap.get(codCli);

                if (coords) {
                    const val = currentFilteredSalesMap.get(codCli) || 0;
                    const formattedVal = val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

                    const rcaCode = client.rca1 || 'N/A';
                    const rcaName = (optimizedData.rcaNameByCode && optimizedData.rcaNameByCode.get(rcaCode)) || rcaCode;

                    // Color Logic
                    // Default: Red (No purchase or <= 0)
                    let markerColor = '#ef4444'; // red-500
                    let statusText = 'Não comprou';

                    if (val > 0) {
                        const mix = currentClientMixStatus.get(codCli) || { elma: false, foods: false };
                        if (mix.elma && mix.foods) {
                            markerColor = '#3b82f6'; // blue-500 (Elma & Foods)
                            statusText = 'Comprou Elma e Foods';
                        } else if (mix.elma) {
                            markerColor = '#22c55e'; // green-500 (Only Elma)
                            statusText = 'Apenas Elma';
                        } else if (mix.foods) {
                            markerColor = '#eab308'; // yellow-500 (Only Foods)
                            statusText = 'Apenas Foods';
                        } else {
                            markerColor = '#9ca3af'; // gray-400 (Other/Unknown)
                            statusText = 'Outros';
                        }
                    }

                    const tooltipContent = `
                        <div class="text-xs">
                            <b>${codCli} - ${client.nomeCliente || 'Cliente'}</b><br>
                            <span class="text-blue-500 font-semibold">RCA: ${rcaName}</span><br>
                            <span class="text-green-600 font-bold">Venda: ${formattedVal}</span><br>
                            <span style="color: ${markerColor}; font-weight: bold;">Status: ${statusText}</span><br>
                            ${client.bairro || ''}, ${client.cidade || ''}
                        </div>
                    `;

                    // Canvas Circle Marker (Performance Optimization)
                    const marker = L.circleMarker([coords.lat, coords.lng], {
                        radius: 6,
                        fillColor: markerColor,
                        color: "#ffffff",
                        weight: 1,
                        opacity: 1,
                        fillOpacity: 0.8
                    });



                    marker.bindTooltip(tooltipContent, { direction: 'top', offset: [0, 0] });
                    clientMarkersLayer.addLayer(marker);
                }
            }, () => {
                areMarkersGenerated = true;
                updateMarkersVisibility();
            });
        }

        let sellerDetailsMap = new Map();
        window.sellerDetailsMap = sellerDetailsMap;
        let supervisorDetailsMap = new Map();
        window.supervisorDetailsMap = supervisorDetailsMap;

        // --- HIERARCHY FILTER SYSTEM ---
        const hierarchyState = {}; // Map<viewPrefix, { coords: Set, cocoords: Set, promotors: Set }>

        window.getHierarchyFilteredClients = getHierarchyFilteredClients;
        function getHierarchyFilteredClients(viewPrefix, sourceClients = allClientsData) {
            const state = hierarchyState[viewPrefix];
            if (!state) return sourceClients;

            const { coords, cocoords, promotors } = state;

            let effectiveCoords = new Set(coords);
            let effectiveCoCoords = new Set(cocoords);
            let effectivePromotors = new Set(promotors);

            // Apply User Context Constraints implicitly?
            if (userHierarchyContext.role === 'coord') effectiveCoords.add(userHierarchyContext.coord);
            if (userHierarchyContext.role === 'cocoord') {
                effectiveCoords.add(userHierarchyContext.coord);
                effectiveCoCoords.add(userHierarchyContext.cocoord);
            }
            if (userHierarchyContext.role === 'promotor') {
                effectiveCoords.add(userHierarchyContext.coord);
                effectiveCoCoords.add(userHierarchyContext.cocoord);
                effectivePromotors.add(userHierarchyContext.promotor);
            }

            const isColumnar = sourceClients instanceof ColumnarDataset;
            const result = [];
            const len = sourceClients.length;

            if (viewPrefix === 'main') {
            }

            let missingNodeCount = 0;

            for(let i=0; i<len; i++) {
                const client = isColumnar ? sourceClients.get(i) : sourceClients[i];
                const codCli = normalizeKey(client['Código'] || client['codigo_cliente']);
                const node = optimizedData.clientHierarchyMap.get(codCli);

                if (!node) {
                    missingNodeCount++;
                    // FIX: Allow Orphans for Admins if no filters are active
                    // For non-admins (Supervisors/Sellers/Promoters), ALWAYS include orphans because init.js already scoped the data to their wallet.
                    if (userHierarchyContext.role === 'adm') {
                        const hasFilters = effectiveCoords.size > 0 || effectiveCoCoords.size > 0 || effectivePromotors.size > 0;
                        if (!hasFilters) {
                            result.push(client);
                        }
                    } else if (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller' && userHierarchyContext.role !== 'promotor') {
                        // Fix for BALCAO missing: Allow orphans for Gerentes in seller mode so they can be processed
                        // by the subsequent RCA/Seller filters instead of being dropped by the hierarchy map
                        result.push(client);
                    } else {
                        result.push(client);
                    }
                    continue; 
                }

                // Check Coord
                if (effectiveCoords.size > 0 && !effectiveCoords.has(node.coord.code)) continue;
                // Check CoCoord
                if (effectiveCoCoords.size > 0 && !effectiveCoCoords.has(node.cocoord.code)) continue;
                // Check Promotor
                if (effectivePromotors.size > 0 && !effectivePromotors.has(node.promotor.code)) continue;

                result.push(client);
            }

            if (viewPrefix === 'main') {
            }
            return result;
        }

        function updateFilterButtonText(element, selectedSet, defaultLabel) {
            if (!element) return;
            if (selectedSet.size === 0) {
                element.textContent = defaultLabel;
            } else if (selectedSet.size === 1) {
                // Find the label for the single selected value?
                // We don't have the label map easily accessible here without passing it.
                // For simplicity, showing count or generic text.
                // Or if we want the label, we'd need to lookup in optimizedData maps.
                // Let's iterate the set to get the value.
                const val = selectedSet.values().next().value;
                // Try to resolve name
                let name = val;
                if (optimizedData.coordMap.has(val)) name = optimizedData.coordMap.get(val);
                else if (optimizedData.cocoordMap.has(val)) name = optimizedData.cocoordMap.get(val);
                else if (optimizedData.promotorMap.has(val)) name = optimizedData.promotorMap.get(val);
                else if (window.sellerDetailsMap && window.sellerDetailsMap.has(val)) name = window.sellerDetailsMap.get(val).name;
                
                element.textContent = name;
            } else {
                element.textContent = `${selectedSet.size} selecionados`;
            }
        }

        function updateVendedorFilterDropdown() {
            // Note: In Promoter Mode, Vendedores logic is strictly tied to hierarchy ('getHierarchyFilteredClients')
            // This differs slightly from standard 'updateGenericVendedorFilter' helper which only relies on 'supervisorsSet'.
            // Because of this custom hierarchy logic dependency, it remains separate here to avoid regressions in Promoter Mode.
            const dropdown = document.getElementById('vendedor-filter-dropdown');
            const text = document.getElementById('vendedor-filter-text');
            if (!dropdown) return;

            let clients;
            if (adminViewMode === 'promoter') {
                clients = getHierarchyFilteredClients('main', allClientsData);
            } else {
                if (selectedSupervisors.size > 0) {
                    clients = [];
                    const len = allClientsData.length;
                    for (let i = 0; i < len; i++) {
                        const c = allClientsData instanceof ColumnarDataset ? allClientsData.get(i) : allClientsData[i];
                        const rca1 = String(c.rca1 || '');
                        const details = sellerDetailsMap.get(rca1);
                        if (details && details.supervisor && selectedSupervisors.has(details.supervisor)) {
                            clients.push(c);
                        }
                    }
                } else {
                    clients = allClientsData;
                }
            }

            const validRcas = new Set();
            const len = clients.length;
            for (let i = 0; i < len; i++) {
                const c = clients instanceof ColumnarDataset ? clients.get(i) : clients[i];
                const rca1 = String(c.rca1 || '').trim();
                if (rca1 && rca1 !== '0' && rca1 !== 'N/A') {
                    validRcas.add(rca1);
                }
            }

            let options = [];
            validRcas.forEach(rca => {
                const details = sellerDetailsMap.get(rca);
                const name = details ? (details.name || rca) : rca;
                options.push({ value: rca, label: name });
            });
            options.sort((a, b) => a.label.localeCompare(b.label));

            let html = `
                <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer border-b border-slate-700/50 mb-1">
                    <span class="text-xs text-orange-400 font-bold uppercase tracking-wider">Selecionar Todos</span>
                    <input type="checkbox" value="ALL" class="form-checkbox h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 rounded focus:ring-[#FF5E00] focus:ring-offset-slate-800 focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                </label>
            `;
            
            options.forEach(opt => {
                const checked = selectedVendedores.has(opt.value) ? 'checked' : '';
                html += `
                    <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer group">
                        <span class="text-xs text-slate-300 group-hover:text-white transition-colors truncate mr-2">${window.escapeHtml(opt.label)}</span>
                        <input type="checkbox" value="${window.escapeHtml(opt.value)}" ${checked} class="form-checkbox h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 rounded focus:ring-[#FF5E00] focus:ring-offset-slate-800 focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    </label>
                `;
            });
            dropdown.innerHTML = html;

            if (typeof updateFilterButtonText === 'function') {
                updateFilterButtonText(text, selectedVendedores, 'Todos');
            }
        }

        function updateSupervisorFilterDropdown() {
            if (typeof window.updateGenericSupervisorFilter === 'function') {
                window.updateGenericSupervisorFilter(
                    'main-supervisor-filter-dropdown',
                    'main-supervisor-filter-text',
                    selectedSupervisors,
                    sellerDetailsMap,
                    updateFilterButtonText,
                    'Todos',
                    'text-[#FF5E00]',
                    (d) => d.supervisor && d.supervisor !== '0' && d.supervisor !== 'N/A'
                );
            }
        }

        function updateHierarchyDropdown(viewPrefix, level) {
            if (viewPrefix === 'comparison') { refreshRpcFacetUI('comparison'); return; }
            if (viewPrefix === 'coverage' || viewPrefix === 'weekly') { refreshRpcFacetUI(viewPrefix); return; }
            const state = hierarchyState[viewPrefix];
            const els = {
                coord: { dd: document.getElementById(`${viewPrefix}-coord-filter-dropdown`), text: document.getElementById(`${viewPrefix}-coord-filter-text`) },
                cocoord: { dd: document.getElementById(`${viewPrefix}-cocoord-filter-dropdown`), text: document.getElementById(`${viewPrefix}-cocoord-filter-text`) },
                promotor: { dd: document.getElementById(`${viewPrefix}-promotor-filter-dropdown`), text: document.getElementById(`${viewPrefix}-promotor-filter-text`) }
            };

            const target = els[level];
            if (!target.dd) return;

            let options = [];
            // Determine available options based on parent selection
            if (level === 'coord') {
                // Show all Coords (or restricted)
                if (userHierarchyContext.role === 'adm') {
                    // ⚡ Bolt Optimization: Use pre-allocated array and direct loop instead of Array.from().map()
                    options = new Array(optimizedData.coordMap.size);
                    let idx = 0;
                    for (const [k, v] of optimizedData.coordMap.entries()) {
                        options[idx++] = { value: k, label: v };
                    }
                } else {
                    // Restricted: Only show own
                    if (userHierarchyContext.coord) {
                        options = [{ value: userHierarchyContext.coord, label: optimizedData.coordMap.get(userHierarchyContext.coord) || userHierarchyContext.coord }];
                    }
                }
            } else if (level === 'cocoord') {
                // Show CoCoords belonging to selected Coords
                let parentCoords = state.coords;
                // If no parent selected, and ADM, show ALL. If restricted, show allowed.
                // If restricted, state.coords might be empty initially, but user context implies restriction.
                
                let allowedCoords = parentCoords;
                if (allowedCoords.size === 0) {
                    if (userHierarchyContext.role === 'adm') {
                        // All coords
                        allowedCoords = new Set(optimizedData.coordMap.keys());
                    } else if (userHierarchyContext.coord) {
                        allowedCoords = new Set([userHierarchyContext.coord]);
                    }
                }

                const validCodes = new Set();
                allowedCoords.forEach(c => {
                    const children = optimizedData.cocoordsByCoord.get(c);
                    if(children) children.forEach(child => validCodes.add(child));
                });



                // Apply User Context Restriction for CoCoord level
                if (userHierarchyContext.role === 'cocoord' || userHierarchyContext.role === 'promotor') {
                    // Restrict to own cocoord
                    if (userHierarchyContext.cocoord && validCodes.has(userHierarchyContext.cocoord)) {
                        validCodes.clear();
                        validCodes.add(userHierarchyContext.cocoord);
                    } else {
                        validCodes.clear(); // Should not happen if data consistent
                    }
                }

                // ⚡ Bolt Optimization: Use pre-allocated array and direct loop instead of Array.from().map()
                options = new Array(validCodes.size);
                let idx = 0;
                for (const c of validCodes) {
                    options[idx++] = { value: c, label: optimizedData.cocoordMap.get(c) || c };
                }
            } else if (level === 'promotor') {
                // Show Promotors belonging to selected CoCoords
                let parentCoCoords = state.cocoords;
                
                let allowedCoCoords = parentCoCoords;
                if (allowedCoCoords.size === 0) {
                    // Need to resolve relevant CoCoords from relevant Coords
                    let relevantCoords = state.coords;
                    if (relevantCoords.size === 0) {
                         if (userHierarchyContext.role === 'adm') relevantCoords = new Set(optimizedData.coordMap.keys());
                         else if (userHierarchyContext.coord) relevantCoords = new Set([userHierarchyContext.coord]);
                    }

                    const validCoCoords = new Set();
                    relevantCoords.forEach(c => {
                        const children = optimizedData.cocoordsByCoord.get(c);
                        if(children) children.forEach(child => validCoCoords.add(child));
                    });


                    
                    // Filter by User Context
                    if (userHierarchyContext.role === 'cocoord' || userHierarchyContext.role === 'promotor') {
                         if (userHierarchyContext.cocoord) {
                             // Only keep own
                             if (validCoCoords.has(userHierarchyContext.cocoord)) {
                                 validCoCoords.clear();
                                 validCoCoords.add(userHierarchyContext.cocoord);
                             }
                         }
                    }
                    allowedCoCoords = validCoCoords;
                }

                const validCodes = new Set();
                allowedCoCoords.forEach(c => {
                    const children = optimizedData.promotorsByCocoord.get(c);
                    if(children) children.forEach(child => validCodes.add(child));
                });



                // Apply User Context Restriction for Promotor level
                if (userHierarchyContext.role === 'promotor') {
                    if (userHierarchyContext.promotor && validCodes.has(userHierarchyContext.promotor)) {
                        validCodes.clear();
                        validCodes.add(userHierarchyContext.promotor);
                    }
                }

                // ⚡ Bolt Optimization: Use pre-allocated array and direct loop instead of Array.from().map()
                options = new Array(validCodes.size);
                let idx = 0;
                for (const c of validCodes) {
                    options[idx++] = { value: c, label: optimizedData.promotorMap.get(c) || c };
                }
            }

            // Sort
            if (options) options.sort((a, b) => a.label.localeCompare(b.label));
            else options = [];

            // Render
            let html = '';
            const selectedSet = state[level + 's']; // coords, cocoords, promotors
            options.forEach(opt => {
                const checked = selectedSet.has(opt.value) ? 'checked' : '';
                html += `
                    <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer">
                        <span class="text-xs text-slate-300 truncate mr-2">${window.escapeHtml(opt.label)}</span>
                        <input type="checkbox" value="${window.escapeHtml(opt.value)}" ${checked} class="form-checkbox h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 rounded focus:ring-[#FF5E00] focus:ring-offset-slate-800 focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    </label>
                `;
            });
            target.dd.innerHTML = html;
            
            // Update Text Label
            let label = 'Todos';
            if (level === 'coord') label = 'Coordenador';
            if (level === 'cocoord') label = 'Co-Coord';
            if (level === 'promotor') label = 'Promotor';

            updateFilterButtonText(target.text, selectedSet, label);
        }

        function applyAdminViewVisibilityRules() {
            const contextRole = (userHierarchyContext && userHierarchyContext.role) ? userHierarchyContext.role : 'adm';
            const isAdm = contextRole === 'adm';
            const isCoord = contextRole === 'coord';
            const isCocoord = contextRole === 'cocoord';
            const isSupervisor = contextRole === 'supervisor';

            // Rules

            // Hierarchy Filters Visibility
            // Show only if in Promoter Mode AND role allows it (Adm, Coord, CoCoord)
            const showCoord = (adminViewMode === 'promoter') && isAdm;
            const showCocoord = (adminViewMode === 'promoter') && (isAdm || isCoord);
            const showPromotor = (adminViewMode === 'promoter') && (isAdm || isCoord || isCocoord);

            // Sales Filters Visibility
            // Show only if in Seller Mode AND role allows it (Adm, Coord, Supervisor)
            // Supervisor hides "Supervisor Filter" because they ARE the supervisor.
            // Seller hides "Supervisor" and "Vendedor" filters (they only see their data).
            const showSupervisor = (adminViewMode === 'seller') && (isAdm || isCoord);
            const showVendedor = (adminViewMode === 'seller') && (isAdm || isCoord || isSupervisor);

            const setVis = (id, show) => {
                const el = document.getElementById(id);
                if (el) {
                    if (show) el.classList.remove('hidden');
                    else el.classList.add('hidden');
                }
            };

            // Main (Overview) - Special IDs
            setVis('main-coord-filter-wrapper', showCoord);
            setVis('main-cocoord-filter-wrapper', showCocoord);
            setVis('main-promotor-filter-wrapper', showPromotor);
            setVis('main-supervisor-filter-wrapper', showSupervisor);
            setVis('vendedor-filter-wrapper', showVendedor);

            // Standard Views Prefixes
            const views = [
                'weekly', 'comparison', 'positivacao', 'city', 'coverage',
                'mix', 'innovations-month', 'titulos', 'lp', 'history', 'meta-realizado'
            ];

            views.forEach(prefix => {
                setVis(`${prefix}-coord-filter-wrapper`, showCoord);
                setVis(`${prefix}-cocoord-filter-wrapper`, showCocoord);
                setVis(`${prefix}-promotor-filter-wrapper`, showPromotor);
                setVis(`${prefix}-supervisor-filter-wrapper`, showSupervisor);
                setVis(`${prefix}-vendedor-filter-wrapper`, showVendedor);
            });

            // Stock View (Only Sales Filters)
            setVis('stock-supervisor-filter-wrapper', showSupervisor);
            setVis('stock-vendedor-filter-wrapper', showVendedor);
        }

        function toggleAdminViewMode() {
            const btn = document.getElementById('admin-view-toggle-btn');
            if (adminViewMode === 'promoter') {
                adminViewMode = 'seller';
                if (btn) {
                    btn.classList.add('text-[#FF5E00]', 'bg-white/10');
                }
            } else {
                adminViewMode = 'promoter';
                if (btn) {
                    btn.classList.remove('text-[#FF5E00]', 'bg-white/10');
                }
            }
            
            applyAdminViewVisibilityRules();
            updateSupervisorFilterDropdown(); 
            updateVendedorFilterDropdown();
            updateDashboard();

            if (currentActiveView === 'comparativo' && typeof updateComparisonView === 'function') {
                if (typeof updateComparisonSupervisorFilter === 'function') updateComparisonSupervisorFilter();
                if (typeof updateComparisonVendedorFilter === 'function') updateComparisonVendedorFilter();
                updateComparisonView();
            } else if (currentActiveView === 'positivacao' && typeof updatePositivacaoView === 'function') {
                if (typeof updatePositivacaoSupervisorFilter === 'function') updatePositivacaoSupervisorFilter();
                if (typeof updatePositivacaoVendedorFilter === 'function') updatePositivacaoVendedorFilter();
                updatePositivacaoView();
            } else if (currentActiveView === 'cidades' && typeof updateCityMap === 'function') {
                if (typeof updateCitySupervisorFilter === 'function') updateCitySupervisorFilter();
                if (typeof updateCityVendedorFilter === 'function') updateCityVendedorFilter();
                updateCityMap();
            } else if (currentActiveView === 'cobertura' && typeof updateCoverageView === 'function') {
                if (typeof updateCoverageSupervisorFilter === 'function') updateCoverageSupervisorFilter();
                if (typeof updateCoverageVendedorFilter === 'function') updateCoverageVendedorFilter();
                updateCoverageView();
            } else if (currentActiveView === 'weekly' && typeof updateWeeklyView === 'function') {
                updateWeeklyView();
            } else if (currentActiveView === 'meta-realizado' && typeof updateMetaRealizadoView === 'function') {
                if (typeof updateMetaRealizadoSupervisorFilter === 'function') updateMetaRealizadoSupervisorFilter();
                if (typeof updateMetaRealizadoVendedorFilter === 'function') updateMetaRealizadoVendedorFilter();
                updateMetaRealizadoView();
            } else if (currentActiveView === 'mix' && typeof updateMixView === 'function') {
                if (typeof updateMixSupervisorFilter === 'function') updateMixSupervisorFilter();
                if (typeof updateMixVendedorFilter === 'function') updateMixVendedorFilter();
                updateMixView();
            }
        }

