        function renderPositivacaoView() {
            setupHierarchyFilters('positivacao', () => handlePositivacaoFilterChange({ excludeFilter: 'hierarchy' }));
            setupPositivacaoSupervisorFilterHandlers();

            // Supplier Filter (New)
            if (positivacaoSupplierFilterDropdown && !positivacaoSupplierFilterDropdown._hasListener) {
                if (positivacaoSupplierFilterBtn) {
                    // Fetch the current text element BEFORE cloning, so we don't lose reference to the original
                    let currentTextEl = document.getElementById('positivacao-supplier-filter-text');

                    const newBtn = positivacaoSupplierFilterBtn.cloneNode(true);
                    positivacaoSupplierFilterBtn.parentNode.replaceChild(newBtn, positivacaoSupplierFilterBtn);

                    // Re-assign the global reference to the cloned elements to prevent modifying detached DOM nodes
                    positivacaoSupplierFilterBtn = newBtn;
                    positivacaoSupplierFilterText = newBtn.querySelector('#positivacao-supplier-filter-text') || currentTextEl;

                    newBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        positivacaoSupplierFilterDropdown.classList.toggle('hidden');
                    });



                    // Close on click outside
                    document.addEventListener('click', (e) => {
                        if (!newBtn.contains(e.target) && !positivacaoSupplierFilterDropdown.contains(e.target)) {
                            positivacaoSupplierFilterDropdown.classList.add('hidden');
                        }
                    });


                }

                positivacaoSupplierFilterDropdown.addEventListener('change', (e) => {
                    if (e.target.type === 'checkbox') {
                        const val = e.target.value;
                        if (e.target.checked) selectedPositivacaoSuppliers.push(val);
                        else selectedPositivacaoSuppliers = selectedPositivacaoSuppliers.filter(s => s !== val);

                        selectedPositivacaoSuppliers = updateSupplierFilter(positivacaoSupplierFilterDropdown, positivacaoSupplierFilterText, selectedPositivacaoSuppliers, [...allSalesData, ...allHistoryData], 'positivacao');
                        handlePositivacaoFilterChange({ excludeFilter: 'supplier' });
                    }
                });


                positivacaoSupplierFilterDropdown._hasListener = true;
            }

            // Setup other filters listeners
            if (positivacaoComRedeBtn && !positivacaoComRedeBtn._hasListener) {
                positivacaoRedeGroupContainer.addEventListener('click', (e) => {
                    const btn = e.target.closest('button');
                    if (!btn) return;

                    const group = btn.dataset.group;
                    positivacaoRedeGroupFilter = group;

                    positivacaoRedeGroupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');

                    if (group === 'com_rede') {
                        positivacaoRedeFilterDropdown.classList.remove('hidden');
                    } else {
                        positivacaoRedeFilterDropdown.classList.add('hidden');
                    }
                    handlePositivacaoFilterChange({ excludeFilter: 'rede' });
                });


                positivacaoComRedeBtn._hasListener = true;
            }

            if (positivacaoRedeFilterDropdown && !positivacaoRedeFilterDropdown._hasListener) {
                positivacaoRedeFilterDropdown.addEventListener('change', () => handlePositivacaoFilterChange({ excludeFilter: 'rede' }));
                positivacaoRedeFilterDropdown._hasListener = true;
            }

            // Client Typeahead
            setupClientTypeahead('positivacao-codcli-filter', 'positivacao-codcli-filter-suggestions', (code) => {
                handlePositivacaoFilterChange({ excludeFilter: 'client' });
            });
            // Manual Input listener for clearing
            if (positivacaoCodCliFilter && !positivacaoCodCliFilter._hasListener) {
                positivacaoCodCliFilter.addEventListener('input', (e) => {
                    if (!e.target.value) handlePositivacaoFilterChange({ excludeFilter: 'client' });
                });


                positivacaoCodCliFilter._hasListener = true;
            }

            // City Filter
            if (positivacaoCityFilter && !positivacaoCityFilter._hasListener) {
                const updateSuggestions = debounce(() => {
                    const val = positivacaoCityFilter.value.trim().toLowerCase();
                    if (val.length < 1) {
                        positivacaoCitySuggestions.classList.add('hidden');
                        return;
                    }

                    const { clients } = getPositivacaoFilteredData({ excludeFilter: 'city' });
                    const uniqueCities = new Set();
                    clients.forEach(c => {
                        if (c.cidade && c.cidade !== 'N/A') uniqueCities.add(c.cidade);
                    });



                    // ⚡ Bolt Optimization: Avoid Array.from().filter() intermediate allocations
                    const matches = [];
                    for (const c of uniqueCities) {
                        if (c.toLowerCase().includes(val)) matches.push(c);
                    }
                    matches.sort();

                    if (matches.length > 0) {
                        positivacaoCitySuggestions.innerHTML = matches.slice(0, 10).map(c => {
                            const safeC = c.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                            return `<div class="p-2 hover:bg-slate-700 cursor-pointer text-sm text-slate-300" data-val="${safeC}">${safeC}</div>`;
                        }).join('');
                        positivacaoCitySuggestions.classList.remove('hidden');
                    } else {
                        positivacaoCitySuggestions.classList.add('hidden');
                    }
                }, 300);

                positivacaoCityFilter.addEventListener('input', (e) => {
                    updateSuggestions();
                    if (!e.target.value) handlePositivacaoFilterChange();
                });



                positivacaoCityFilter.addEventListener('focus', () => {
                    if (positivacaoCityFilter.value.trim().length >= 1) {
                         positivacaoCitySuggestions.classList.remove('hidden');
                    }
                });



                // Delegation for suggestions click
                positivacaoCitySuggestions.addEventListener('click', (e) => {
                    const item = e.target.closest('div');
                    if (item && item.dataset.val) {
                        positivacaoCityFilter.value = item.dataset.val;
                        positivacaoCitySuggestions.classList.add('hidden');
                        handlePositivacaoFilterChange();
                    }
                });



                // Close suggestions on click outside
                document.addEventListener('click', (e) => {
                    if (!positivacaoCityFilter.contains(e.target) && !positivacaoCitySuggestions.contains(e.target)) {
                        positivacaoCitySuggestions.classList.add('hidden');
                    }
                });



                positivacaoCityFilter._hasListener = true;
            }

            if (clearPositivacaoFiltersBtn && !clearPositivacaoFiltersBtn._hasListener) {
                clearPositivacaoFiltersBtn.addEventListener('click', resetPositivacaoFilters);
                clearPositivacaoFiltersBtn._hasListener = true;
            }

            const pActivePrev = document.getElementById('positivacao-active-prev-btn');
            if (pActivePrev && !pActivePrev._hasListener) {
                pActivePrev.addEventListener('click', () => {
                    if(positivacaoActiveState.page > 1) {
                        positivacaoActiveState.page--;
                        renderPositivacaoActiveTable();
                    }
                });


                pActivePrev._hasListener = true;

                document.getElementById('positivacao-active-next-btn').addEventListener('click', () => {
                    const max = Math.ceil(positivacaoActiveState.data.length / positivacaoActiveState.limit);
                    if(positivacaoActiveState.page < max) {
                        positivacaoActiveState.page++;
                        renderPositivacaoActiveTable();
                    }
                });



                document.getElementById('positivacao-inactive-prev-btn').addEventListener('click', () => {
                    if(positivacaoInactiveState.page > 1) {
                        positivacaoInactiveState.page--;
                        renderPositivacaoInactiveTable();
                    }
                });



                document.getElementById('positivacao-inactive-next-btn').addEventListener('click', () => {
                    const max = Math.ceil(positivacaoInactiveState.data.length / positivacaoInactiveState.limit);
                    if(positivacaoInactiveState.page < max) {
                        positivacaoInactiveState.page++;
                        renderPositivacaoInactiveTable();
                    }
                });


            }

            // Initial Update
            updateAllPositivacaoFilters();
            updatePositivacaoView();
        }

        function getPositivacaoFilteredData(options = {}) {
            const { excludeFilter = null } = options;

            // 1. Base Clients (Hierarchy vs Seller)
            let clients;
            if (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller') {
                clients = [];
                const hasSup = selectedPositivacaoSupervisors.size > 0;
                const hasVend = selectedPositivacaoVendedores.size > 0;

                const source = allClientsData;
                const len = source.length;

                for(let i=0; i<len; i++) {
                    const c = source instanceof ColumnarDataset ? source.get(i) : source[i];
                    // Basic active check (similar to getActiveClientsData but simpler)
                    const rca1 = String(c.rca1 || '').trim();
                    const isAmericanas = c.isAmericanas !== undefined ? c.isAmericanas : (c.isAmericanas = (c.razaoSocial || '').toUpperCase().includes('AMERICANAS'));
                    
                    // FIX: Only filter orphans for Admins
                    if (window.userRole === 'adm' && !isAmericanas && rca1 === '') continue; // Skip strictly inactive

                    let keep = true;
                    if (hasSup || hasVend) {
                        const details = sellerDetailsMap.get(rca1);
                        if (hasSup) {
                            if (!details || !selectedPositivacaoSupervisors.has(details.supervisor)) keep = false;
                        }
                        if (keep && hasVend) {
                            if (!selectedPositivacaoVendedores.has(rca1)) keep = false;
                        }
                    }

                    if (keep) clients.push(c);
                }
            } else {
                clients = getHierarchyFilteredClients('positivacao', allClientsData);
            }

            // 2. Filter by Rede, Client, etc.
            const isComRede = positivacaoRedeGroupFilter === 'com_rede';
            const isSemRede = positivacaoRedeGroupFilter === 'sem_rede';
            const redeSet = (isComRede && selectedPositivacaoRedes.length > 0) ? new Set(selectedPositivacaoRedes) : null;
            const clientFilter = positivacaoCodCliFilter.value.trim().toLowerCase();
            const cityFilter = positivacaoCityFilter.value.trim().toLowerCase();

            if (positivacaoRedeGroupFilter || clientFilter || cityFilter) {
                 const temp = [];
                 const len = clients.length;
                 const checkRede = excludeFilter !== 'rede';
                 const checkClient = excludeFilter !== 'client' && !!clientFilter;
                 const checkCity = excludeFilter !== 'city' && !!cityFilter;

                 for(let i=0; i<len; i++) {
                     const c = clients[i];
                     if (checkRede) {
                        if (isComRede) {
                            if (!c.ramo || c.ramo === 'N/A') continue;
                            if (redeSet && !redeSet.has(c.ramo)) continue;
                        } else if (isSemRede) {
                            if (c.ramo && c.ramo !== 'N/A') continue;
                        }
                     }
                     if (checkCity) {
                         const cCity = (c.cidade || '').toLowerCase();
                         if (!cCity.includes(cityFilter)) continue;
                     }
                     if (checkClient) {
                        const code = String(c['Código'] || c['codigo_cliente']).toLowerCase();
                        const name = (c.nomeCliente || '').toLowerCase();
                        const city = (c.cidade || '').toLowerCase();
                        const bairro = (c.bairro || '').toLowerCase();
                        const cnpj = String(c['CNPJ/CPF'] || c.cnpj_cpf || '').replace(/\D/g, '');

                        if (!code.includes(clientFilter) && !name.includes(clientFilter) && !city.includes(clientFilter) && !bairro.includes(clientFilter) && !cnpj.includes(clientFilter)) continue;
                     }
                     temp.push(c);
                 }
                 clients = temp;
            }

            // Get matching sales
            const clientCodes = new Set();
            for(let i=0; i<clients.length; i++) clientCodes.add(clients[i]['Código']);

            const filters = {
                clientCodes: clientCodes
            };

            // Add Supplier Filter
            if (selectedPositivacaoSuppliers && selectedPositivacaoSuppliers.length > 0) {
                filters.supplier = new Set(selectedPositivacaoSuppliers);
            }

            const sales = getFilteredDataFromIndices(optimizedData.indices.current, optimizedData.salesById, filters);

            return { clients, sales };
        }

        function updateAllPositivacaoFilters(options = {}) {
            const { skipFilter = null } = options;

            // Populate Supplier Filter (if not skipping or if initializing)
            if (skipFilter !== 'supplier') {
                // For Suppliers, we usually show ALL options, not filtered by clients?
                // The main updateSupplierFilter handles it using global data source.
                selectedPositivacaoSuppliers = updateSupplierFilter(positivacaoSupplierFilterDropdown, positivacaoSupplierFilterText, selectedPositivacaoSuppliers, [...allSalesData, ...allHistoryData], 'positivacao');
            }

            if (skipFilter !== 'rede') {
                 const { clients } = getPositivacaoFilteredData({ excludeFilter: 'rede' });
                 if (positivacaoRedeGroupFilter === 'com_rede') {
                     selectedPositivacaoRedes = updateRedeFilter(positivacaoRedeFilterDropdown, positivacaoComRedeBtnText, selectedPositivacaoRedes, clients);
                 }
            }
        }

        function handlePositivacaoFilterChange(options = {}) {
            if (window.positivacaoUpdateTimeout) clearTimeout(window.positivacaoUpdateTimeout);
            window.positivacaoUpdateTimeout = setTimeout(() => {
                updateAllPositivacaoFilters(options);
                updatePositivacaoView();
            }, 10);
        }

        function resetPositivacaoFilters() {

            if (hierarchyState['positivacao']) {
                hierarchyState['positivacao'].coords.clear();
                hierarchyState['positivacao'].cocoords.clear();
                hierarchyState['positivacao'].promotors.clear();
            }

            if (typeof selectedPositivacaoSupervisors !== 'undefined') selectedPositivacaoSupervisors.clear();
            if (typeof selectedPositivacaoVendedores !== 'undefined') selectedPositivacaoVendedores.clear();

            if (typeof updatePositivacaoSupervisorFilter === 'function') updatePositivacaoSupervisorFilter();
            if (typeof updatePositivacaoVendedorFilter === 'function') updatePositivacaoVendedorFilter();

            selectedPositivacaoCoords = [];
            selectedPositivacaoCoCoords = [];
            selectedPositivacaoPromotors = [];
            selectedPositivacaoRedes = [];
            selectedPositivacaoSuppliers = []; // Reset Supplier
            positivacaoRedeGroupFilter = '';
            positivacaoCodCliFilter.value = '';
            if (positivacaoCityFilter) positivacaoCityFilter.value = '';

            if (positivacaoRedeGroupContainer) {
                positivacaoRedeGroupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
                positivacaoRedeGroupContainer.querySelector('button[data-group=""]').classList.add('active');
            }
            if (positivacaoRedeFilterDropdown) positivacaoRedeFilterDropdown.classList.add('hidden');
            if (positivacaoSupplierFilterDropdown) positivacaoSupplierFilterDropdown.classList.add('hidden');

            setupHierarchyFilters('positivacao');
            updateAllPositivacaoFilters();
            updatePositivacaoView();
        }

        function updatePositivacaoView() {
            positivacaoDataForExport = { active: [], inactive: [] };
            positivacaoRenderId++;
            const currentRenderId = positivacaoRenderId;

            if (positivacaoActiveDetailTableBody) positivacaoActiveDetailTableBody.innerHTML = getSkeletonRows(7, 5);
            if (positivacaoInactiveDetailTableBody) positivacaoInactiveDetailTableBody.innerHTML = getSkeletonRows(6, 5);

            const { clients, sales } = getPositivacaoFilteredData();

            const clientTotals = new Map();
            const clientDetails = new Map();

            sales.forEach(s => {
                const cod = s.CODCLI;
                const val = Number(s.VLVENDA) || 0;
                clientTotals.set(cod, (clientTotals.get(cod) || 0) + val);

                if (!clientDetails.has(cod)) clientDetails.set(cod, { pepsico: 0, multimarcas: 0 });
                const d = clientDetails.get(cod);
                const pasta = s.OBSERVACAOFOR || s.PASTA;
                if (pasta === 'PEPSICO') d.pepsico += val;
                else if (pasta === 'MULTIMARCAS') d.multimarcas += val;
            });

            const activeList = [];
            const inactiveList = [];

            runAsyncChunked(clients, (c) => {
                const cod = String(c['Código'] || c['codigo_cliente']);
                const total = clientTotals.get(cod) || 0;

                const registrationDate = parseDate(c.dataCadastro);
                const now = lastSaleDate;
                const isNew = registrationDate && registrationDate.getUTCMonth() === now.getUTCMonth() && registrationDate.getUTCFullYear() === now.getUTCFullYear();

                if (total >= 1) {
                    const det = clientDetails.get(cod) || { pepsico: 0, multimarcas: 0 };
                    activeList.push({
                        ...c,
                        total,
                        pepsico: det.pepsico,
                        multimarcas: det.multimarcas,
                        outros: total - det.pepsico - det.multimarcas,
                        isNew
                    });


                } else {
                    c.isReturn = (total < 0);
                    c.isNewForInactiveLabel = isNew && !parseDate(c.ultimaCompra);
                    inactiveList.push(c);
                }
            }, () => {
                if (currentRenderId !== positivacaoRenderId) return;

                activeList.sort((a, b) => b.total - a.total);
                inactiveList.sort((a, b) => (parseDate(b.ultimaCompra) || 0) - (parseDate(a.ultimaCompra) || 0));

                positivacaoDataForExport.active = activeList;
                positivacaoDataForExport.inactive = inactiveList;

                positivacaoActiveState.data = activeList;
                positivacaoActiveState.page = 1;

                positivacaoInactiveState.data = inactiveList;
                positivacaoInactiveState.page = 1;

                renderPositivacaoActiveTable();
                renderPositivacaoInactiveTable();
            });
        }

        function renderPositivacaoActiveTable() {
            const tbody = document.getElementById('positivacao-active-detail-table-body');
            if (!tbody) return;

            // Clear existing content (Optimized cleanup)
            while (tbody.firstChild) {
                tbody.removeChild(tbody.firstChild);
            }

            const { page, limit, data } = positivacaoActiveState;
            const total = data.length;
            const start = (page - 1) * limit;
            const end = start + limit;
            const subset = data.slice(start, end);
            const totalPages = Math.ceil(total / limit) || 1;

            // --- Optimization: Use DocumentFragment and Template ---
            let template = document.getElementById('positivacao-active-row-template');
            if (!template) {
                template = document.createElement('template');
                template.id = 'positivacao-active-row-template';
                template.innerHTML = `
                <tr class="hover:bg-slate-700">
                    <!-- Desktop Columns -->
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm"><a href="#" class="text-teal-400 hover:underline"></a></td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm truncate max-w-[120px] md:max-w-xs"></td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-right text-[10px] md:text-sm">
                        <div class="tooltip">
                            <span class="tooltip-text" style="width: max-content; transform: translateX(-50%); margin-left: 0;"></span>
                        </div>
                    </td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm"></td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm"></td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-center text-[10px] md:text-sm"></td>
                    <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm"></td>

                    <!-- Mobile Card Layout -->
                    <td class="md:hidden w-full p-3 border-b border-white/5 block">
                        <div class="flex justify-between items-center mb-1">
                            <div class="flex items-center gap-2 overflow-hidden">
                                <a href="#" class="text-cyan-400 font-mono font-bold text-sm hover:underline shrink-0"></a>
                                <span class="text-slate-300 text-xs font-medium truncate"></span>
                            </div>
                            <span class="text-green-400 font-bold text-sm shrink-0 ml-2"></span>
                        </div>
                        <div class="text-xs text-slate-500 font-medium truncate uppercase"></div>
                    </td>
                </tr>`;
                document.body.appendChild(template);
            }

            // Pre-create Label element for cloning
            const novoSpan = document.createElement('span');
            novoSpan.className = 'ml-2 text-xs font-semibold text-purple-400 bg-purple-900/50 px-2 py-0.5 rounded-full';
            novoSpan.textContent = 'NOVO';

            const fragment = document.createDocumentFragment();

            for (let i = 0; i < subset.length; i++) {
                const item = subset[i];
                const clone = template.content.cloneNode(true);
                const tr = clone.firstElementChild;
                const cells = tr.cells;

                // Precompute values
                const code = item['Código'];
                const name = item.nomeCliente || 'N/A';
                const city = item.cidade || 'N/A';
                const bairro = item.bairro || 'N/A';
                const rcaVal = (item.rcas && item.rcas.length > 0) ? item.rcas[0] : '-';
                const fantasia = item.fantasia || '';
                const totalFormatted = item.total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

                // Tooltip Logic
                let tooltipParts = [];
                if (item.pepsico > 0) tooltipParts.push(`PEPSICO: ${item.pepsico.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`);
                if (item.multimarcas > 0) tooltipParts.push(`MULTIMARCAS: ${item.multimarcas.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`);
                if (item.outros > 0.001) tooltipParts.push(`OUTROS: ${item.outros.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}`);
                const tooltipText = tooltipParts.length > 0 ? tooltipParts.join('<br>') : 'Sem detalhamento';

                // --- Populate Desktop Columns ---

                // 0: Code Link
                const link0 = cells[0].firstElementChild;
                link0.textContent = code;
                link0.dataset.codcli = code;

                // 1: Name + Label
                cells[1].title = name;
                cells[1].textContent = name;
                if (item.isNew) {
                    cells[1].appendChild(novoSpan.cloneNode(true));
                }

                // 2: Total + Tooltip
                const tooltipDiv = cells[2].firstElementChild;
                const tooltipSpan = tooltipDiv.firstElementChild;
                // Insert text before the span (safer than innerHTML on parent)
                tooltipDiv.insertBefore(document.createTextNode(totalFormatted), tooltipSpan);
                tooltipSpan.innerHTML = tooltipText;

                // 3: City
                cells[3].textContent = city;

                // 4: Bairro
                cells[4].textContent = bairro;

                // 5: Date
                cells[5].textContent = formatDate(item.ultimaCompra);

                // 6: RCA
                cells[6].textContent = rcaVal;

                // --- Populate Mobile Layout ---
                // Structure: td > (div > (div > (a, span), span), div)
                const mobileContainer = cells[7];
                const row1 = mobileContainer.firstElementChild;
                const row2 = mobileContainer.lastElementChild; // Fantasia

                const leftGroup = row1.firstElementChild;
                const totalSpanMobile = row1.lastElementChild;

                const linkMobile = leftGroup.firstElementChild;
                const nameSpanMobile = leftGroup.children[1];

                linkMobile.textContent = code;
                linkMobile.dataset.codcli = code;
                nameSpanMobile.textContent = name;

                if (item.isNew) {
                    leftGroup.appendChild(novoSpan.cloneNode(true));
                }

                totalSpanMobile.textContent = totalFormatted;
                row2.textContent = fantasia;

                fragment.appendChild(clone);
            }

            tbody.appendChild(fragment);

            // Update Pagination Controls
            document.getElementById('positivacao-active-prev-btn').disabled = page === 1;
            document.getElementById('positivacao-active-next-btn').disabled = page >= totalPages;
            document.getElementById('positivacao-active-page-info').textContent = `${start + 1}-${Math.min(end, total)} de ${total}`;
        }

        function renderPositivacaoInactiveTable() {
            const tbody = document.getElementById('positivacao-inactive-detail-table-body');
            if (!tbody) return;

            const { page, limit, data } = positivacaoInactiveState;
            const total = data.length;
            const start = (page - 1) * limit;
            const end = start + limit;
            const subset = data.slice(start, end);
            const totalPages = Math.ceil(total / limit) || 1;

            tbody.innerHTML = subset.map(client => {
                const novoLabel = client.isNewForInactiveLabel ? `<span class="ml-2 text-[9px] md:text-xs font-semibold text-purple-400 bg-purple-900/50 px-1 py-0.5 rounded-full">NOVO</span>` : '';
                const rcaVal = (client.rcas && client.rcas.length > 0) ? client.rcas[0] : '-';
                const razaoSocial = client.nomeCliente || 'N/A';
                const fantasia = client.fantasia || client.FANTASIA || client.Fantasia || client['Nome Fantasia'] || client.razaoSocial || client.nomeCliente || '';
                const cidade = client.cidade || 'N/A';
                const bairro = client.bairro || 'N/A';
                const ultCompra = client.ultimaCompra || client['Data da Última Compra'];
                const formattedDate = formatDate(ultCompra);

                return `<tr class="hover:bg-slate-700">
                            <!-- Desktop Columns -->
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm"><a href="#" class="text-teal-400 hover:underline" data-codcli="${window.escapeHtml(client['Código'])}">${window.escapeHtml(client['Código'])}</a></td>
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 flex items-center text-[10px] md:text-sm truncate max-w-[120px] md:max-w-xs" title="${window.escapeHtml(razaoSocial)}">${window.escapeHtml(razaoSocial)}${novoLabel}</td>
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm">${window.escapeHtml(cidade)}</td>
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm">${window.escapeHtml(bairro)}</td>
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-center text-[10px] md:text-sm">${formattedDate}</td>
                            <td class="hidden md:table-cell px-2 py-2 md:px-4 md:py-2 text-[10px] md:text-sm">${window.escapeHtml(rcaVal)}</td>

                            <!-- Mobile Card Layout -->
                            <td class="md:hidden w-full p-3 border-b border-white/5 block">
                                <div class="flex justify-between items-center mb-1">
                                    <div class="flex items-center gap-2 overflow-hidden">
                                        <a href="#" class="text-cyan-400 font-mono font-bold text-sm hover:underline shrink-0" data-codcli="${window.escapeHtml(client['Código'])}">${window.escapeHtml(client['Código'])}</a>
                                        <span class="text-slate-300 text-xs font-medium truncate">${window.escapeHtml(razaoSocial)}</span>
                                        ${novoLabel}
                                    </div>
                                    <span class="text-slate-400 font-bold text-xs shrink-0 ml-2">${formattedDate}</span>
                                </div>
                                <div class="text-xs text-slate-500 font-medium truncate uppercase">${window.escapeHtml(fantasia)}</div>
                            </td>
                        </tr>`;
            }).join('');

            // Update Pagination Controls
            document.getElementById('positivacao-inactive-prev-btn').disabled = page === 1;
            document.getElementById('positivacao-inactive-next-btn').disabled = page >= totalPages;
            document.getElementById('positivacao-inactive-page-info').textContent = `${start + 1}-${Math.min(end, total)} de ${total}`;
        }

        // --- TITULOS VIEW LOGIC ---
        let titulosTableState = { page: 1, limit: 50, filteredData: [] };
        let selectedTitulosRedes = [];
        let titulosRedeGroupFilter = '';
        let titulosRenderId = 0;

        function getTitulosUserRole() {
            if (window.userIsSupervisor) return 'supervisor';
            if (window.userIsSeller) return 'seller';

            let role = (window.userHierarchyContext?.role || '').trim().toLowerCase();
            if (!role) {
                role = (window.userRole || '').trim().toLowerCase();
            }

            if (role === 'adm' || role === 'admin') return 'adm';
            if (role === 'coord' || role === 'coordenador') return 'coord';
            if (role === 'cocoord' || role === 'co-coordenador' || role === 'cocoordenador') return 'cocoord';
            if (role === 'supervisor') return 'supervisor';
            if (role === 'promotor' || role === 'vendedor' || role === 'user' || role === 'seller') return 'promotor';

            return 'adm';
        }

                function applyTitulosFilterVisibilityRules() {
            if (typeof updateHierarchyFiltersVisibility === 'function') {
                updateHierarchyFiltersVisibility();
                return;
            }
            const role = getTitulosUserRole();

            const filialWrapper = document.getElementById('titulos-filial-filter-wrapper');
            const coordWrapper = document.getElementById('titulos-coord-filter-wrapper');
            const cocoordWrapper = document.getElementById('titulos-cocoord-filter-wrapper');
            const supervisorWrapper = document.getElementById('titulos-supervisor-filter-wrapper');
            const promotorWrapper = document.getElementById('titulos-promotor-filter-wrapper');
            const vendedorWrapper = document.getElementById('titulos-vendedor-filter-wrapper');
            const redeWrapper = document.getElementById('titulos-rede-filter-wrapper');

            // Filial & Rede: Sempre visíveis
            if (filialWrapper) filialWrapper.classList.remove('hidden');
            if (redeWrapper) redeWrapper.classList.remove('hidden');

            const isSellerMode = typeof adminViewMode !== 'undefined' && adminViewMode === 'seller';

            if (role === 'adm') {
                if (coordWrapper) coordWrapper.classList.toggle('hidden', isSellerMode);
                if (cocoordWrapper) cocoordWrapper.classList.toggle('hidden', isSellerMode);
                if (promotorWrapper) promotorWrapper.classList.toggle('hidden', isSellerMode);
                if (supervisorWrapper) supervisorWrapper.classList.toggle('hidden', !isSellerMode);
                if (vendedorWrapper) vendedorWrapper.classList.toggle('hidden', !isSellerMode);
            } else if (role === 'coord') {
                if (coordWrapper) coordWrapper.classList.add('hidden');
                if (cocoordWrapper) cocoordWrapper.classList.toggle('hidden', isSellerMode);
                if (promotorWrapper) promotorWrapper.classList.toggle('hidden', isSellerMode);
                if (supervisorWrapper) supervisorWrapper.classList.toggle('hidden', !isSellerMode);
                if (vendedorWrapper) vendedorWrapper.classList.toggle('hidden', !isSellerMode);
            } else if (role === 'cocoord') {
                if (coordWrapper) coordWrapper.classList.add('hidden');
                if (cocoordWrapper) cocoordWrapper.classList.add('hidden');
                if (promotorWrapper) promotorWrapper.classList.toggle('hidden', isSellerMode);
                if (supervisorWrapper) supervisorWrapper.classList.add('hidden');
                if (vendedorWrapper) vendedorWrapper.classList.toggle('hidden', !isSellerMode);
            } else {
                if (coordWrapper) coordWrapper.classList.add('hidden');
                if (cocoordWrapper) cocoordWrapper.classList.add('hidden');
                if (supervisorWrapper) supervisorWrapper.classList.add('hidden');
                if (promotorWrapper) promotorWrapper.classList.add('hidden');
                if (vendedorWrapper) vendedorWrapper.classList.add('hidden');
            }
        }

        async function renderTitulosView() {
            applyTitulosFilterVisibilityRules();
            setupHierarchyFilters('titulos', () => handleTitulosFilterChange());
            setupTitulosSupervisorFilterHandlers();
            if (typeof setupGenericFilialFilterHandlers === 'function') {
                setupGenericFilialFilterHandlers('titulos', () => handleTitulosFilterChange());
            }

            // Rede Filters
            const redeGroupContainer = document.getElementById('titulos-rede-group-container');
            const comRedeBtn = document.getElementById('titulos-com-rede-btn');
            const comRedeBtnText = document.getElementById('titulos-com-rede-btn-text');
            const redeDropdown = document.getElementById('titulos-rede-filter-dropdown');

            if (redeGroupContainer && !redeGroupContainer._hasListener) {
                redeGroupContainer.addEventListener('click', (e) => {
                    const btn = e.target.closest('button');
                    if (!btn) return;
                    const group = btn.dataset.group;
                    titulosRedeGroupFilter = group;
                    redeGroupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    if (group === 'com_rede') redeDropdown.classList.remove('hidden');
                    else redeDropdown.classList.add('hidden');
                    handleTitulosFilterChange();
                });
                redeGroupContainer._hasListener = true;
            }

            if (redeDropdown && !redeDropdown._hasListener) {
                redeDropdown.addEventListener('change', () => handleTitulosFilterChange());
                redeDropdown._hasListener = true;
            }

            // Client Search
            setupClientTypeahead('titulos-codcli-filter', 'titulos-codcli-filter-suggestions', (code) => {
                handleTitulosFilterChange();
            });
            const clientInput = document.getElementById('titulos-codcli-filter');
            if (clientInput && !clientInput._hasListener) {
                clientInput.addEventListener('input', (e) => {
                     if (!e.target.value) handleTitulosFilterChange();
                });
                clientInput._hasListener = true;
            }

            // City Filter
            const cityInput = document.getElementById('titulos-city-filter');
            if (cityInput && !cityInput._hasListener) {
                const suggestions = document.getElementById('titulos-city-suggestions');

                const updateSuggestions = debounce(() => {
                    const val = cityInput.value.trim().toLowerCase();
                    if (val.length < 1) {
                        suggestions.classList.add('hidden');
                        return;
                    }

                    const cities = new Set();
                    const clients = getHierarchyFilteredClients('titulos', allClientsData);
                    clients.forEach(c => {
                        if (c.cidade && c.cidade !== 'N/A') cities.add(c.cidade);
                    });

                    const matches = [];
                    for (const c of cities) {
                        if (c.toLowerCase().includes(val)) matches.push(c);
                    }
                    matches.sort();

                    if (matches.length > 0) {
                        suggestions.innerHTML = matches.slice(0, 10).map(c => {
                             const safeC = c.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                             return `<div class="p-2 hover:bg-slate-700 cursor-pointer text-sm text-slate-300" data-val="${safeC}">${safeC}</div>`;
                        }).join('');
                        suggestions.classList.remove('hidden');
                    } else {
                        suggestions.classList.add('hidden');
                    }
                }, 300);

                cityInput.addEventListener('input', (e) => {
                    updateSuggestions();
                    if (!e.target.value) handleTitulosFilterChange();
                });

                cityInput.addEventListener('focus', () => {
                    if (cityInput.value.trim().length >= 1) {
                         suggestions.classList.remove('hidden');
                    }
                });

                suggestions.addEventListener('click', (e) => {
                    const item = e.target.closest('div');
                    if (item && item.dataset.val) {
                        cityInput.value = item.dataset.val;
                        suggestions.classList.add('hidden');
                        handleTitulosFilterChange();
                    }
                });

                document.addEventListener('click', (e) => {
                    if (!cityInput.contains(e.target) && !suggestions.contains(e.target)) {
                        suggestions.classList.add('hidden');
                    }
                });

                cityInput._hasListener = true;
            }

            // Clear Btn
            const clearBtn = document.getElementById('clear-titulos-filters-btn');
            if(clearBtn && !clearBtn._hasListener) {
                clearBtn.addEventListener('click', () => {
                     resetTitulosFilters();
                });
                clearBtn._hasListener = true;
            }

            // Pagination
            const prevBtn = document.getElementById('titulos-prev-page-btn');
            const nextBtn = document.getElementById('titulos-next-page-btn');
            if(prevBtn && !prevBtn._hasListener) {
                prevBtn.addEventListener('click', () => {
                    if(titulosTableState.page > 1) {
                        titulosTableState.page--;
                        updateTitulosView();
                    }
                });
                prevBtn._hasListener = true;
            }
            if(nextBtn && !nextBtn._hasListener) {
                nextBtn.addEventListener('click', () => {
                    const max = Math.ceil(titulosTableState.totalRows / titulosTableState.limit);
                    if(titulosTableState.page < max) {
                        titulosTableState.page++;
                        updateTitulosView();
                    }
                });
                nextBtn._hasListener = true;
            }

            // Initial Filter Population (Rede)
            updateTitulosRedeFilter();

            // Initial Render
            updateTitulosView();
        }

        function updateTitulosRedeFilter() {
            const clients = getHierarchyFilteredClients('titulos', allClientsData);
            const dropdown = document.getElementById('titulos-rede-filter-dropdown');
            const btnText = document.getElementById('titulos-com-rede-btn-text');
            if(dropdown) {
                selectedTitulosRedes = updateRedeFilter(dropdown, btnText, selectedTitulosRedes, clients);
            }
        }

        function handleTitulosFilterChange() {
             titulosTableState.page = 1;
             if(window.titulosUpdateTimeout) clearTimeout(window.titulosUpdateTimeout);
             window.titulosUpdateTimeout = setTimeout(() => {
                 updateTitulosView();
             }, 10);
        }

        function resetTitulosFilters() {
            selectedTitulosRedes = [];
            titulosRedeGroupFilter = '';
            document.getElementById('titulos-codcli-filter').value = '';
            if(document.getElementById('titulos-city-filter')) document.getElementById('titulos-city-filter').value = '';

            const filialInput = document.getElementById('titulos-filial-filter');
            if (filialInput) filialInput.value = 'all';
            const filialText = document.getElementById('titulos-filial-filter-text');
            if (filialText) filialText.textContent = 'Todas (05 + 08)';
            const filialRadios = document.querySelectorAll('input[name="titulos-filial"]');
            if (filialRadios) {
                filialRadios.forEach(r => r.checked = (r.value === 'all'));
            }

            if (hierarchyState['titulos']) {
                hierarchyState['titulos'].coords.clear();
                hierarchyState['titulos'].cocoords.clear();
                hierarchyState['titulos'].promotors.clear();
            }

            if (typeof selectedTitulosSupervisors !== 'undefined') selectedTitulosSupervisors.clear();
            if (typeof selectedTitulosVendedores !== 'undefined') selectedTitulosVendedores.clear();

            if (typeof updateTitulosSupervisorFilter === 'function') updateTitulosSupervisorFilter();
            if (typeof updateTitulosVendedorFilter === 'function') updateTitulosVendedorFilter();

            const groupContainer = document.getElementById('titulos-rede-group-container');
            if(groupContainer) {
                 groupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
                 groupContainer.querySelector('button[data-group=""]').classList.add('active');
            }
            const dd = document.getElementById('titulos-rede-filter-dropdown');
            if(dd) dd.classList.add('hidden');

            setupHierarchyFilters('titulos');
            applyTitulosFilterVisibilityRules();
            updateTitulosRedeFilter();
            titulosTableState.page = 1;
            updateTitulosView();
        }

        async function updateTitulosView() {
            titulosRenderId++;
            const currentId = titulosRenderId;

            const tbody = document.getElementById('titulos-table-body');
            if (tbody) tbody.innerHTML = getSkeletonRows(8, 5);

            applyTitulosFilterVisibilityRules();

            // Extract Filter Params based on visible filter elements
            const filialWrapper = document.getElementById('titulos-filial-filter-wrapper');
            const isFilialVisible = filialWrapper && !filialWrapper.classList.contains('hidden');
            const filialInput = document.getElementById('titulos-filial-filter');
            const filialVal = filialInput ? filialInput.value : 'all';
            let p_filial = null;
            if (isFilialVisible && filialVal && filialVal !== 'all' && filialVal !== 'ambas') {
                const unpadded = filialVal.replace(/^0+/, '') || filialVal;
                const padded = filialVal.length < 2 ? filialVal.padStart(2, '0') : filialVal;
                p_filial = Array.from(new Set([filialVal, unpadded, padded]));
            }

            const cityInput = document.getElementById('titulos-city-filter');
            const cityVal = cityInput ? cityInput.value.trim() : '';
            const p_cidade = cityVal ? [cityVal] : null;

            const clientInput = document.getElementById('titulos-codcli-filter');
            const searchVal = clientInput ? clientInput.value.trim() : '';
            const p_search = searchVal || null;

            const redeWrapper = document.getElementById('titulos-rede-filter-wrapper');
            const isRedeVisible = redeWrapper && !redeWrapper.classList.contains('hidden');
            let p_rede = null;
            if (isRedeVisible) {
                if (titulosRedeGroupFilter === 'com_rede') {
                    p_rede = selectedTitulosRedes.length > 0 ? selectedTitulosRedes : ['C/ REDE'];
                } else if (titulosRedeGroupFilter === 'sem_rede') {
                    p_rede = ['S/ REDE'];
                }
            }

            const coordWrapper = document.getElementById('titulos-coord-filter-wrapper');
            const isCoordVisible = coordWrapper && !coordWrapper.classList.contains('hidden');
            let p_coordenador = null;
            if (isCoordVisible && hierarchyState['titulos']?.coords && hierarchyState['titulos'].coords.size > 0) {
                p_coordenador = Array.from(hierarchyState['titulos'].coords);
            }

            const cocoordWrapper = document.getElementById('titulos-cocoord-filter-wrapper');
            const isCoCoordVisible = cocoordWrapper && !cocoordWrapper.classList.contains('hidden');
            let p_cocoordenador = null;
            if (isCoCoordVisible && hierarchyState['titulos']?.cocoords && hierarchyState['titulos'].cocoords.size > 0) {
                p_cocoordenador = Array.from(hierarchyState['titulos'].cocoords);
            }

            const supervisorWrapper = document.getElementById('titulos-supervisor-filter-wrapper');
            const isSupervisorVisible = supervisorWrapper && !supervisorWrapper.classList.contains('hidden');
            let p_supervisor = null;
            if (isSupervisorVisible && selectedTitulosSupervisors && selectedTitulosSupervisors.size > 0) {
                p_supervisor = Array.from(selectedTitulosSupervisors);
            }

            const promotorWrapper = document.getElementById('titulos-promotor-filter-wrapper');
            const vendedorWrapper = document.getElementById('titulos-vendedor-filter-wrapper');
            const isPromotorVisible = (promotorWrapper && !promotorWrapper.classList.contains('hidden')) || (vendedorWrapper && !vendedorWrapper.classList.contains('hidden'));
            let p_vendedor = null;
            if (isPromotorVisible) {
                const vendedorSet = new Set();
                if (hierarchyState['titulos']?.promotors) {
                    hierarchyState['titulos'].promotors.forEach(p => vendedorSet.add(p));
                }
                if (selectedTitulosVendedores) {
                    selectedTitulosVendedores.forEach(v => vendedorSet.add(v));
                }
                if (vendedorSet.size > 0) {
                    p_vendedor = Array.from(vendedorSet);
                }
            }

            const pageParam = (titulosTableState.page || 1) - 1;
            const limitParam = titulosTableState.limit || 50;

            try {
                const rpcParams = {
                    p_page: pageParam,
                    p_limit: limitParam
                };
                if (p_filial !== null && p_filial !== undefined) rpcParams.p_filial = p_filial;
                if (p_cidade !== null && p_cidade !== undefined) rpcParams.p_cidade = p_cidade;
                if (p_supervisor !== null && p_supervisor !== undefined) rpcParams.p_supervisor = p_supervisor;
                if (p_vendedor !== null && p_vendedor !== undefined) rpcParams.p_vendedor = p_vendedor;
                if (p_coordenador !== null && p_coordenador !== undefined) rpcParams.p_coordenador = p_coordenador;
                if (p_cocoordenador !== null && p_cocoordenador !== undefined) rpcParams.p_cocoordenador = p_cocoordenador;
                if (p_rede !== null && p_rede !== undefined) rpcParams.p_rede = p_rede;
                if (p_search !== null && p_search !== undefined) rpcParams.p_search = p_search;

                const { data, error } = await window.supabaseClient.rpc('get_titulos_view_data', rpcParams);

                if (currentId !== titulosRenderId) return;

                if (error) {
                    console.warn('[Titulos RPC] Error:', error);
                    fallbackLocalTitulosView();
                    return;
                }

                const res = typeof data === 'string' ? JSON.parse(data) : data;
                const kpis = res.kpis || {};
                const rows = res.rows || [];

                titulosTableState.totalRows = kpis.total_rows || 0;

                // Process rows into titulosTableState.filteredData format
                const today = new Date();
                today.setHours(0,0,0,0);
                const criticalDate = new Date();
                criticalDate.setDate(today.getDate() - 60);

                let criticalDebt = 0;
                const uniqueClientsCriticalSet = new Set();

                titulosTableState.filteredData = rows.map(r => {
                    const dtVenc = r.dt_vencimento ? parseDate(r.dt_vencimento) : null;
                    const valReceber = Number(r.vl_receber) || 0;
                    const valOriginal = Number(r.vl_titulos) || 0;

                    let isCritical = false;
                    let daysOverdue = 0;

                    if (dtVenc && valReceber > 0) {
                        if (dtVenc < criticalDate) {
                            isCritical = true;
                        }
                        if (dtVenc < today) {
                            const diffTime = Math.abs(today - dtVenc);
                            daysOverdue = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                        }
                    }

                    if (isCritical) {
                        criticalDebt += valReceber;
                        if (r.cod_cliente) uniqueClientsCriticalSet.add(r.cod_cliente);
                    }

                    return {
                        codCli: r.cod_cliente || 'N/A',
                        clientName: r.nomecliente || r.razaosocial || r.fantasia || 'Desconhecido',
                        rcaName: r.vendedor_nome || 'N/A',
                        city: r.cidade || 'N/A',
                        dtVenc: dtVenc,
                        valReceber: valReceber,
                        valOriginal: valOriginal,
                        isCritical: isCritical,
                        daysOverdue: daysOverdue
                    };
                });

                renderTitulosKPIs(
                    kpis.total_receber !== undefined ? kpis.total_receber : (kpis.total_vl_receber || 0),
                    kpis.critical_receber !== undefined ? kpis.critical_receber : criticalDebt,
                    kpis.critical_clients !== undefined ? kpis.critical_clients : uniqueClientsCriticalSet.size,
                    kpis.total_rows || 0
                );
                renderTitulosRpcTable(rows);

            } catch (err) {
                console.error('[Titulos RPC] Exception:', err);
                if (currentId === titulosRenderId) {
                    fallbackLocalTitulosView();
                }
            }
        }

        function fallbackLocalTitulosView() {
            const rawTitulos = embeddedData.titulos;
            if (!rawTitulos || !rawTitulos.length) {
                renderTitulosKPIs(0, 0, 0, 0);
                titulosTableState.filteredData = [];
                titulosTableState.totalRows = 0;
                renderTitulosTable();
                return;
            }

            let allowedClients;
            if (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller') {
                allowedClients = [];
                const hasSup = selectedTitulosSupervisors.size > 0;
                const hasVend = selectedTitulosVendedores.size > 0;
                const source = allClientsData;
                const len = source.length;
                for(let i=0; i<len; i++) {
                    const c = source instanceof ColumnarDataset ? source.get(i) : source[i];
                    const rca1 = String(c.rca1 || '').trim();
                    const isAmericanas = c.isAmericanas !== undefined ? c.isAmericanas : (c.isAmericanas = (c.razaoSocial || '').toUpperCase().includes('AMERICANAS'));
                    if (window.userRole === 'adm' && !isAmericanas && rca1 === '') continue;
                    let keep = true;
                    if (hasSup || hasVend) {
                        const details = sellerDetailsMap.get(rca1);
                        if (hasSup) {
                            const cSup = c.supervisor || c.Supervisor || (details ? details.supervisor : '');
                            let matchSup = false;
                            if (cSup && selectedTitulosSupervisors.has(cSup)) {
                                matchSup = true;
                            } else if (details && details.supervisor && selectedTitulosSupervisors.has(details.supervisor)) {
                                matchSup = true;
                            } else if (cSup || (details && details.supervisor)) {
                                const supName = cSup || (details ? details.supervisor : '');
                                for (let s of selectedTitulosSupervisors) {
                                    if (supName.toUpperCase().includes(s.toUpperCase()) || s.toUpperCase().includes(supName.toUpperCase())) {
                                        matchSup = true;
                                        break;
                                    }
                                }
                            }
                            if (!matchSup) keep = false;
                        }
                        if (keep && hasVend) {
                            if (!selectedTitulosVendedores.has(rca1)) keep = false;
                        }
                    }
                    if (keep) allowedClients.push(c);
                }
            } else {
                allowedClients = getHierarchyFilteredClients('titulos', allClientsData);
            }

            const filialInput = document.getElementById('titulos-filial-filter');
            const filialVal = filialInput ? filialInput.value : 'all';
            const hasFilial = filialVal && filialVal !== 'all' && filialVal !== 'ambas';
            const selectedFilialStr = hasFilial ? String(filialVal).trim() : null;
            const unpaddedFilial = hasFilial ? selectedFilialStr.replace(/^0+/, '') : null;

            const hasSupFilter = selectedTitulosSupervisors && selectedTitulosSupervisors.size > 0;

            const cityToBranchMap = new Map();
            if (hasFilial && window.embeddedData && window.embeddedData.config_city_branches) {
                window.embeddedData.config_city_branches.forEach(r => {
                    if (r.cidade && r.filial) {
                        const normCity = String(r.cidade).normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase().trim();
                        cityToBranchMap.set(normCity, String(r.filial).trim());
                    }
                });
            }

            if (hasFilial || hasSupFilter) {
                const filteredList = [];
                for (let i = 0; i < allowedClients.length; i++) {
                    const c = allowedClients[i];
                    if (hasFilial) {
                        let cFilial = String(c.filial || c.Filial || '').trim();
                        if (!cFilial) {
                            const rawCity = String(c.cidade || c.Cidade || '').trim();
                            if (rawCity) {
                                const normCity = rawCity.normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase().trim();
                                cFilial = cityToBranchMap.get(normCity) || '';
                            }
                        }
                        const cFilialUnpadded = cFilial.replace(/^0+/, '');
                        if (cFilial !== selectedFilialStr && cFilialUnpadded !== unpaddedFilial) {
                            continue;
                        }
                    }
                    if (hasSupFilter) {
                        const rca1 = String(c.rca1 || c.RCA1 || '').trim();
                        const details = sellerDetailsMap ? sellerDetailsMap.get(rca1) : null;
                        const cSup = c.supervisor || c.Supervisor || (details ? details.supervisor : '');
                        let matchSup = false;
                        if (cSup && selectedTitulosSupervisors.has(cSup)) {
                            matchSup = true;
                        } else if (details && details.supervisor && selectedTitulosSupervisors.has(details.supervisor)) {
                            matchSup = true;
                        } else if (cSup) {
                            for (let s of selectedTitulosSupervisors) {
                                if (cSup.toUpperCase().includes(s.toUpperCase()) || s.toUpperCase().includes(cSup.toUpperCase())) {
                                    matchSup = true;
                                    break;
                                }
                            }
                        }
                        if (!matchSup) continue;
                    }
                    filteredList.push(c);
                }
                allowedClients = filteredList;
            }

            const isComRede = titulosRedeGroupFilter === 'com_rede';
            const isSemRede = titulosRedeGroupFilter === 'sem_rede';
            const redeSet = (isComRede && selectedTitulosRedes.length > 0) ? new Set(selectedTitulosRedes) : null;
            const clientSearch = document.getElementById('titulos-codcli-filter').value.toLowerCase().trim();

            const allowedClientCodes = new Set();
            for(let i=0; i<allowedClients.length; i++) {
                const c = allowedClients[i];
                if (isComRede) {
                    if (!c.ramo || c.ramo === 'N/A') continue;
                    if (redeSet && !redeSet.has(c.ramo)) continue;
                } else if (isSemRede) {
                    if (c.ramo && c.ramo !== 'N/A') continue;
                }
                if (clientSearch) {
                    const clientCodeVal = c.cod_cliente || c.codigo_cliente || c['Código'] || c.codigo || c.codCli || '';
                    const code = String(clientCodeVal).toLowerCase();
                    const name = String(c.nomeCliente || c.nomecliente || c.razaoSocial || c.razaosocial || '').toLowerCase();
                    if (!code.includes(clientSearch) && !name.includes(clientSearch)) continue;
                }
                const clientCodeKey = c.cod_cliente || c.codigo_cliente || c['Código'] || c.codigo || c.codCli;
                allowedClientCodes.add(normalizeKey(clientCodeKey));
            }

            const filteredTitulos = [];
            const isCol = rawTitulos instanceof ColumnarDataset;
            const len = rawTitulos.length;

            let colCodCliente, colVlReceber, colVlTitulos, colDtVencimento;
            if (isCol && rawTitulos._data) {
                colCodCliente = rawTitulos._data['cod_cliente'] || rawTitulos._data['COD_CLIENTE'];
                colVlReceber = rawTitulos._data['vl_receber'] || rawTitulos._data['VL_RECEBER'];
                colVlTitulos = rawTitulos._data['vl_titulos'] || rawTitulos._data['VL_TITULOS'];
                colDtVencimento = rawTitulos._data['dt_vencimento'] || rawTitulos._data['DT_VENCIMENTO'];
            }

            const getVal = (i, col) => {
                const val = isCol ? (rawTitulos._data[col] ? rawTitulos._data[col][i] : undefined) : rawTitulos[i][col];
                if (val !== undefined) return val;
                const colUpper = col.toUpperCase();
                return isCol ? (rawTitulos._data[colUpper] ? rawTitulos._data[colUpper][i] : undefined) : rawTitulos[i][colUpper];
            };

            let totalReceber = 0;
            let countCritical = 0;
            const today = new Date();
            today.setHours(0,0,0,0);
            const criticalDate = new Date();
            criticalDate.setDate(today.getDate() - 60);

            for (let i=0; i<len; i++) {
                const rawCodCli = colCodCliente ? colCodCliente[i] : getVal(i, 'cod_cliente');
                const codCli = normalizeKey(rawCodCli);

                if (allowedClientCodes.has(codCli)) {
                    const valReceber = Number(colVlReceber ? colVlReceber[i] : getVal(i, 'vl_receber')) || 0;
                    const valOriginal = Number(colVlTitulos ? colVlTitulos[i] : getVal(i, 'vl_titulos')) || 0;
                    const dtVenc = parseDate(colDtVencimento ? colDtVencimento[i] : getVal(i, 'dt_vencimento'));

                    totalReceber += valReceber;
                    let isCritical = false;
                    let daysOverdue = 0;

                    if (dtVenc && valReceber > 0) {
                        if (dtVenc < criticalDate) {
                            isCritical = true;
                            countCritical++;
                        }
                        if (dtVenc < today) {
                            const diffTime = Math.abs(today - dtVenc);
                            daysOverdue = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                        }
                    }

                    const clientObj = clientMapForKPIs.get(codCli);
                    let clientName = 'Desconhecido';
                    let rcaName = 'N/A';
                    let city = 'N/A';

                    if (clientObj) {
                        let c = clientObj;
                        if (typeof clientObj === 'number') c = allClientsData.get(clientObj);
                        clientName = c.nomeCliente || c.fantasia || 'N/A';
                        city = c.cidade || 'N/A';
                        const rcaCode = String(c.rca1 || '').trim();
                        if (optimizedData.rcaNameByCode && optimizedData.rcaNameByCode.has(rcaCode)) {
                            rcaName = optimizedData.rcaNameByCode.get(rcaCode) || rcaCode;
                        } else {
                            rcaName = rcaCode;
                        }
                    }

                    filteredTitulos.push({
                        codCli,
                        clientName,
                        rcaName,
                        city,
                        dtVenc,
                        valReceber,
                        valOriginal,
                        isCritical,
                        daysOverdue
                    });
                }
            }

            titulosTableState.filteredData = filteredTitulos;
            titulosTableState.totalRows = filteredTitulos.length;
            titulosTableState.filteredData.sort((a,b) => (a.dtVenc || 0) - (b.dtVenc || 0));

            const totalCount = filteredTitulos.length;
            let criticalDebt = 0;
            const uniqueClientsCriticalSet = new Set();
            for (let j = 0; j < totalCount; j++) {
                const t = filteredTitulos[j];
                if (t.isCritical) {
                    criticalDebt += t.valReceber;
                    uniqueClientsCriticalSet.add(t.codCli);
                }
            }

            renderTitulosKPIs(totalReceber, criticalDebt, uniqueClientsCriticalSet.size, totalCount);
            renderTitulosTable();
        }

        function renderTitulosKPIs(total, critical, criticalCount, count) {
            document.getElementById('titulos-kpi-total-debt').textContent = total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
            document.getElementById('titulos-kpi-critical-debt').textContent = critical.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
            document.getElementById('titulos-kpi-critical-count').textContent = `${criticalCount} Clientes Críticos`;
            document.getElementById('titulos-kpi-count').textContent = count;
        }

        function renderTitulosRpcTable(rows) {
            const tbody = document.getElementById('titulos-table-body');
            if(!tbody) return;

            const total = titulosTableState.totalRows || rows.length;
            const limit = titulosTableState.limit || 50;
            const page = titulosTableState.page || 1;
            const start = (page - 1) * limit;
            const end = start + rows.length;
            const totalPages = Math.ceil(total / limit) || 1;

            if (rows.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="text-center py-8 text-slate-500">Nenhum título encontrado.</td></tr>';
                document.getElementById('titulos-page-info-text').textContent = '0 de 0';
                return;
            }

            const today = new Date();
            today.setHours(0,0,0,0);
            const criticalDate = new Date();
            criticalDate.setDate(today.getDate() - 60);

            tbody.innerHTML = rows.map((r, localIndex) => {
                const dtVenc = r.dt_vencimento ? parseDate(r.dt_vencimento) : null;
                const valReceber = Number(r.vl_receber) || 0;
                const valOriginal = Number(r.vl_titulos) || 0;

                let isCritical = false;
                let daysOverdue = 0;

                if (dtVenc && valReceber > 0) {
                    if (dtVenc < criticalDate) isCritical = true;
                    if (dtVenc < today) {
                        const diffTime = Math.abs(today - dtVenc);
                        daysOverdue = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                    }
                }

                const dateStr = dtVenc ? dtVenc.toLocaleDateString('pt-BR') : '-';
                const valOrig = valOriginal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
                const valOpen = valReceber.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

                const clientName = r.nomecliente || r.razaosocial || r.fantasia || 'Desconhecido';
                let mobileClientName = clientName.trim();
                if (mobileClientName.length > 21) {
                    mobileClientName = mobileClientName.substring(0, 21) + '...';
                }

                let statusDesktop = isCritical
                    ? `<span class="px-2 py-1 bg-red-900/50 text-red-300 text-[10px] font-bold rounded-full border border-red-800">${daysOverdue} Dias</span>`
                    : `<span class="px-2 py-1 bg-green-900/50 text-green-300 text-[10px] font-bold rounded-full border border-green-800">Em Aberto</span>`;

                let statusMobile = isCritical
                    ? `<span class="px-2 py-0.5 bg-red-900/50 text-red-300 text-[10px] font-bold rounded-full border border-red-800">${daysOverdue} Dias</span>`
                    : `<span class="px-2 py-0.5 bg-green-900/50 text-green-300 text-[10px] font-bold rounded-full border border-green-800">Em Aberto</span>`;

                const codCli = r.cod_cliente || 'N/A';
                const rcaName = r.vendedor_nome || 'N/A';
                const city = r.cidade || 'N/A';

                return `
                    <tr class="hover:bg-slate-700/50 border-b border-white/5 transition-colors cursor-pointer md:cursor-default" onclick="if(window.innerWidth < 768) openTitulosMobileModal(${localIndex})">
                        <td class="px-4 py-3 font-mono text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(codCli)}</td>
                        <td class="px-4 py-3 text-sm text-white font-medium truncate max-w-[200px] hidden md:table-cell" title="${window.escapeHtml(clientName)}">${window.escapeHtml(clientName)}</td>
                        <td class="px-4 py-3 text-xs text-slate-300 hidden md:table-cell">${window.escapeHtml(rcaName)}</td>
                        <td class="px-4 py-3 text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(city)}</td>
                        <td class="px-4 py-3 text-xs text-white text-center font-mono hidden md:table-cell">${dateStr}</td>
                        <td class="px-4 py-3 text-xs text-slate-500 text-right hidden md:table-cell">${valOrig}</td>
                        <td class="px-4 py-3 text-sm text-white font-bold text-right hidden md:table-cell">${valOpen}</td>
                        <td class="px-4 py-3 text-center hidden md:table-cell">${statusDesktop}</td>

                        <td class="md:hidden mobile-card-header w-full text-left" colspan="8">
                            <div class="flex flex-col gap-2 text-left">
                                <div class="flex justify-between items-center text-left">
                                    <span class="text-xs font-bold text-white leading-tight truncate mr-2 text-left">
                                        ${window.escapeHtml(codCli)} - ${window.escapeHtml(mobileClientName)}
                                    </span>
                                    <div class="shrink-0">
                                        ${statusMobile}
                                    </div>
                                </div>
                                <div class="flex justify-between items-center text-left">
                                    <span class="text-sm font-bold text-white text-left">
                                        ${valOpen}
                                    </span>
                                    <span class="text-sm text-slate-400 font-mono">
                                        ${dateStr}
                                    </span>
                                </div>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            document.getElementById('titulos-prev-page-btn').disabled = page === 1;
            document.getElementById('titulos-next-page-btn').disabled = page >= totalPages;
            document.getElementById('titulos-page-info-text').textContent = `${start + 1}-${Math.min(end, total)} de ${total}`;
        }

        function renderTitulosTable() {
            const tbody = document.getElementById('titulos-table-body');
            if(!tbody) return;

            const { page, limit, filteredData } = titulosTableState;
            const total = titulosTableState.totalRows || filteredData.length;
            const start = (page - 1) * limit;
            const end = start + limit;
            const subset = filteredData.slice(start, end);
            const totalPages = Math.ceil(total / limit) || 1;

            if (total === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="text-center py-8 text-slate-500">Nenhum título encontrado.</td></tr>';
                document.getElementById('titulos-page-info-text').textContent = '0 de 0';
                return;
            }

            tbody.innerHTML = subset.map((t, localIndex) => {
                const globalIndex = start + localIndex;
                const dateStr = t.dtVenc ? t.dtVenc.toLocaleDateString('pt-BR') : '-';
                const valOrig = t.valOriginal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
                const valOpen = t.valReceber.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

                let mobileClientName = (t.clientName || '').trim();
                if (mobileClientName.length > 21) {
                    mobileClientName = mobileClientName.substring(0, 21) + '...';
                }

                let statusDesktop;
                let statusMobile;

                if (t.isCritical) {
                     statusDesktop = `<span class="px-2 py-1 bg-red-900/50 text-red-300 text-[10px] font-bold rounded-full border border-red-800">${t.daysOverdue} Dias</span>`;
                     statusMobile = `<span class="px-2 py-0.5 bg-red-900/50 text-red-300 text-[10px] font-bold rounded-full border border-red-800">${t.daysOverdue} Dias</span>`;
                } else {
                     statusDesktop = `<span class="px-2 py-1 bg-green-900/50 text-green-300 text-[10px] font-bold rounded-full border border-green-800">Em Aberto</span>`;
                     statusMobile = `<span class="px-2 py-0.5 bg-green-900/50 text-green-300 text-[10px] font-bold rounded-full border border-green-800">Em Aberto</span>`;
                }

                return `
                    <tr class="hover:bg-slate-700/50 border-b border-white/5 transition-colors cursor-pointer md:cursor-default" onclick="if(window.innerWidth < 768) openTitulosMobileModal(${localIndex})">
                        <td class="px-4 py-3 font-mono text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(t.codCli)}</td>
                        <td class="px-4 py-3 text-sm text-white font-medium truncate max-w-[200px] hidden md:table-cell" title="${window.escapeHtml(t.clientName)}">${window.escapeHtml(t.clientName)}</td>
                        <td class="px-4 py-3 text-xs text-slate-300 hidden md:table-cell">${window.escapeHtml(t.rcaName)}</td>
                        <td class="px-4 py-3 text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(t.city)}</td>
                        <td class="px-4 py-3 text-xs text-white text-center font-mono hidden md:table-cell">${dateStr}</td>
                        <td class="px-4 py-3 text-xs text-slate-500 text-right hidden md:table-cell">${valOrig}</td>
                        <td class="px-4 py-3 text-sm text-white font-bold text-right hidden md:table-cell">${valOpen}</td>
                        <td class="px-4 py-3 text-center hidden md:table-cell">${statusDesktop}</td>

                        <td class="md:hidden mobile-card-header w-full text-left" colspan="8">
                            <div class="flex flex-col gap-2 text-left">
                                <div class="flex justify-between items-center text-left">
                                    <span class="text-xs font-bold text-white leading-tight truncate mr-2 text-left">
                                        ${window.escapeHtml(t.codCli)} - ${window.escapeHtml(mobileClientName)}
                                    </span>
                                    <div class="shrink-0">
                                        ${statusMobile}
                                    </div>
                                </div>
                                <div class="flex justify-between items-center text-left">
                                    <span class="text-sm font-bold text-white text-left">
                                        ${valOpen}
                                    </span>
                                    <span class="text-sm text-slate-400 font-mono">
                                        ${dateStr}
                                    </span>
                                </div>
                            </div>
                        </td>
                    </tr>
                `;
            }).join('');

            document.getElementById('titulos-prev-page-btn').disabled = page === 1;
            document.getElementById('titulos-next-page-btn').disabled = page >= totalPages;
            document.getElementById('titulos-page-info-text').textContent = `${start + 1}-${Math.min(end, total)} de ${total}`;
        }

    window.openTitulosMobileModal = function(index) {
        if (!titulosTableState.filteredData || !titulosTableState.filteredData[index]) return;
        const t = titulosTableState.filteredData[index];

        const modal = document.getElementById('titulos-mobile-modal');
        document.getElementById('titulos-mobile-modal-title').textContent = t.clientName;
        document.getElementById('titulos-mobile-modal-subtitle').textContent = `Cód: ${t.codCli}`;

        document.getElementById('titulos-modal-seller').textContent = t.rcaName || 'N/A';
        document.getElementById('titulos-modal-city').textContent = t.city || 'N/A';
        document.getElementById('titulos-modal-val-orig').textContent = t.valOriginal.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
        document.getElementById('titulos-modal-val-open').textContent = t.valReceber.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
        document.getElementById('titulos-modal-date').textContent = t.dtVenc ? t.dtVenc.toLocaleDateString('pt-BR') : '-';

        const statusContainer = document.getElementById('titulos-modal-status');
        if (t.isCritical) {
             statusContainer.innerHTML = `<span class="px-3 py-1 bg-red-900/50 text-red-300 text-xs font-bold rounded-full border border-red-800">${t.daysOverdue} Dias em Atraso</span>`;
        } else {
             statusContainer.innerHTML = `<span class="px-3 py-1 bg-green-900/50 text-green-300 text-xs font-bold rounded-full border border-green-800">Em Aberto</span>`;
        }

        const closeBtn = document.getElementById('titulos-mobile-modal-close-btn');
        if (closeBtn) {
            closeBtn.onclick = () => {
                modal.classList.add('hidden');
            };
        }

        modal.onclick = (e) => {
            if (e.target === modal) modal.classList.add('hidden');
        };

        modal.classList.remove('hidden');
    };

        function setupLpFilialFilterHandlers() {
            let filiais = new Set();
            if (window.embeddedData && window.embeddedData.config_city_branches) {
                window.embeddedData.config_city_branches.forEach(r => {
                    if (r.filial) filiais.add(r.filial.trim().toUpperCase());
                });
            }

            const dropdown = document.getElementById('lp-filial-filter-dropdown');
            if (dropdown) {
                let html = `
                    <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer group">
                        <span class="text-xs text-slate-300 group-hover:text-white transition-colors">Todas</span>
                        <input type="radio" name="lp-filial" value="all" checked class="form-radio h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 focus:ring-[#FF5E00] focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    </label>
                `;

                // Add known filiais (sorted)
                Array.from(filiais).sort().forEach(f => {
                    html += `
                        <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer group">
                            <span class="text-xs text-slate-300 group-hover:text-white transition-colors">${f}</span>
                            <input type="radio" name="lp-filial" value="${f}" class="form-radio h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 focus:ring-[#FF5E00] focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                        </label>
                    `;
                });

                // Add fallback for Desconhecida
                html += `
                    <label class="flex items-center justify-between p-2 hover:bg-slate-700 rounded cursor-pointer group">
                        <span class="text-xs text-slate-300 group-hover:text-white transition-colors">Desconhecida</span>
                        <input type="radio" name="lp-filial" value="desconhecida" class="form-radio h-4 w-4 text-[#FF5E00] bg-slate-700 border-slate-600 focus:ring-[#FF5E00] focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    </label>
                `;

                dropdown.innerHTML = html;
            }

            if (typeof window.setupGenericFilialFilterHandlers === 'function') {
                window.setupGenericFilialFilterHandlers('lp', () => handleLpFilterChange({ excludeFilter: 'filial' }));
            }
        }

        function setupLpResearcherFilterHandlers() {
        if (typeof window.setupGenericCheckboxFilterHandlers === 'function') {
            window.setupGenericCheckboxFilterHandlers(
                'lp-researcher',
                selectedLpResearchers,
                () => {
                    updateFilterButtonText(document.getElementById('lp-researcher-filter-text'), selectedLpResearchers, 'Todos');
                    handleLpFilterChange({ excludeFilter: 'researcher' });
                }
            );
        }
        updateLpResearcherFilter();
    }

    function updateLpResearcherFilter() {
        const dropdown = document.getElementById('lp-researcher-filter-dropdown');
        if(!dropdown) return;

        // Re-implement simplified filtering logic just to get available researchers (Pre-Research Filter)
        let allowedClientCodes = new Set();
        const clients = (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller') 
            ? (() => {
                    // Seller Mode Logic
                    const list = [];
                    const hasSup = selectedLpSupervisors.size > 0;
                    const hasVend = selectedLpVendedores.size > 0;
                    for(let i=0; i<allClientsData.length; i++) {
                    const c = allClientsData instanceof ColumnarDataset ? allClientsData.get(i) : allClientsData[i];
                    const rca1 = String(c.rca1 || '').trim();
                    let keep = true;
                    if (hasSup || hasVend) {
                        const details = sellerDetailsMap.get(rca1);
                        if (hasSup && (!details || !selectedLpSupervisors.has(details.supervisor))) keep = false;
                        if (keep && hasVend && !selectedLpVendedores.has(rca1)) keep = false;
                    }
                    if (keep) list.push(c);
                    }
                    return list;
                })()
            : getHierarchyFilteredClients('lp', allClientsData);

            // Apply Rede & Search
            const isComRede = lpRedeGroupFilter === 'com_rede';
            const isSemRede = lpRedeGroupFilter === 'sem_rede';
            const redeSet = (isComRede && selectedLpRedes.length > 0) ? new Set(selectedLpRedes) : null;
            const clientSearch = document.getElementById('lp-codcli-filter') ? document.getElementById('lp-codcli-filter').value.toLowerCase().trim() : '';

            clients.forEach(c => {
                if (isComRede) {
                if (!c.ramo || c.ramo === 'N/A') return;
                if (redeSet && !redeSet.has(c.ramo)) return;
                } else if (isSemRede) {
                if (c.ramo && c.ramo !== 'N/A') return;
                }
                if (clientSearch) {
                const code = String(c['Código'] || c['codigo_cliente']).toLowerCase();
                const name = (c.nomeCliente || '').toLowerCase();
                if (!code.includes(clientSearch) && !name.includes(clientSearch)) return;
                }
                allowedClientCodes.add(normalizeKey(c['Código'] || c['codigo_cliente']));
            });

            // Scan Nota Perfeita
            const researchers = new Set();
            if (embeddedData.nota_perfeita) {
                embeddedData.nota_perfeita.forEach(row => {
                    if (allowedClientCodes.has(normalizeKey(row.codigo_cliente))) {
                        if (row.pesquisador) researchers.add(row.pesquisador.trim());
                    }
                });


            }

            // Sort and Render
            const sortedResearchers = Array.from(researchers).sort();
            let html = '';
            
            sortedResearchers.forEach(res => {
                const rawPesquisador = (res || '').trim();
                const normRes = window.normalizeResearcherCode(rawPesquisador);
                const upperResKey = rawPesquisador.toUpperCase();

                // Resolve friendly name
                let label = res;
                let subtext = '';

                if (typeof optimizedData !== 'undefined' && optimizedData.promotorMap && optimizedData.promotorMap.has(upperResKey)) {
                    let pName = optimizedData.promotorMap.get(upperResKey);
                    pName = pName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();
                    label = pName || rawPesquisador;
                    subtext = rawPesquisador;
                } else if (lpResearcherMap.has(normRes)) {
                    const info = lpResearcherMap.get(normRes);
                    let rawName = info.sellerName || info.sellerCode;
                    rawName = rawName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();

                    if (rawName && rawName !== info.sellerCode) {
                        label = rawName;
                    } else {
                        label = info.sellerCode;
                    }
                    subtext = info.sellerCode;
                } else {
                    // Fallback
                    label = rawPesquisador.toUpperCase();
                    subtext = rawPesquisador.toUpperCase();
                    console.log(`[DEBUG] Fallback ativado para ${rawPesquisador} (normRes: ${normRes}, upperResKey: ${upperResKey})`);
                }

                const checked = selectedLpResearchers.has(res) ? 'checked' : '';
                html += `
                <label class="flex items-center p-2 hover:bg-slate-700 rounded cursor-pointer group border-b border-white/5 last:border-0">
                    <input type="checkbox" value="${window.escapeHtml(res)}" ${checked} class="form-checkbox h-4 w-4 text-orange-500 rounded bg-slate-700 border-slate-600 shrink-0 focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    <div class="ml-2 flex flex-col min-w-0">
                        <span class="text-xs text-slate-300 truncate font-bold group-hover:text-white transition-colors">${window.escapeHtml(label)}</span>
                        ${subtext ? `<span class="text-[9px] text-slate-500 truncate">${window.escapeHtml(subtext)}</span>` : ''}
                    </div>
                </label>
                `;
            });

            dropdown.innerHTML = html;
            updateFilterButtonText(document.getElementById('lp-researcher-filter-text'), selectedLpResearchers, 'Todos');
    }

    let lpState = { page: 1, limit: 50, filteredData: [], allowedClientCodes: new Set() };
    let selectedLpRedes = [];
    let lpRedeGroupFilter = "";
        const filialInput = document.getElementById('lp-filial-filter');
        if (filialInput) filialInput.value = 'all';
        const filialText = document.getElementById('lp-filial-filter-text');
        if (filialText) filialText.textContent = 'Todas';
        const filialRadios = document.querySelectorAll('input[name="lp-filial"]');
        if (filialRadios) {
            filialRadios.forEach(r => r.checked = r.value === 'all');
        }

    let lpRenderId = 0;

    async function exportLpPDF() {
    if (!lpState.filteredData?.length) {
        window.showToast('warning', 'Aguarde a atualização ou selecione filtros com dados para exportar.');
        return;
    }
    if (!window.jspdf || !window.jspdf.jsPDF) {
        window.showToast('error', 'Biblioteca jsPDF não carregada.');
        return;
    }

    try {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF('landscape');
        
        // Use the filtered data that's already in the view state
        const data = lpState.filteredData || [];

        const isPromoterMode = typeof adminViewMode !== 'undefined' && adminViewMode === 'promoter';

        // Group data by filial
        const filialMap = new Map(); // key -> map of agents

        data.forEach(row => {
            const resKey = window.normalizeResearcherCode(row.pesquisador);
            const isRowPromotor = resKey.toUpperCase().includes('PROMOTOR');
            
            if (isPromoterMode && !isRowPromotor) return;
            if (!isPromoterMode && isRowPromotor) return;

            let agentCode = resKey;
            let agentName = row.pesquisador;

            const rawPesquisador = (row.pesquisador || '').trim();
            const upperResKey = rawPesquisador.toUpperCase();

            if (typeof optimizedData !== 'undefined' && optimizedData.promotorMap && optimizedData.promotorMap.has(upperResKey)) {
                let pName = optimizedData.promotorMap.get(upperResKey);
                pName = pName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();
                agentName = pName || rawPesquisador;
                agentCode = upperResKey; // Using uppercase code as key
            } else if (lpResearcherMap && lpResearcherMap.has(resKey)) {
                const info = lpResearcherMap.get(resKey);
                agentCode = info.sellerCode;
                let rawName = info.sellerName || info.sellerCode;
                rawName = rawName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();
                
                if (rawName && rawName !== info.sellerCode) {
                    agentName = rawName;
                } else {
                    agentName = info.sellerCode;
                }
            } else {
                agentName = rawPesquisador.toUpperCase();
            }

            const filialKey = row.filial || 'DESCONHECIDA';

            if (!filialMap.has(filialKey)) {
                filialMap.set(filialKey, new Map());
            }

            const agentMap = filialMap.get(filialKey);

            if (!agentMap.has(agentCode)) {
                agentMap.set(agentCode, {
                    code: agentCode,
                    name: agentName,
                    clients: new Set(),
                    lojasPerfeitas: new Set(),
                    totalScores: 0,
                    auditoriaCount: 0
                });
            }

            const agent = agentMap.get(agentCode);
            if (row.codigo_cliente) {
                agent.clients.add(normalizeKey(row.codigo_cliente));
                if (row.nota_media >= 80) agent.lojasPerfeitas.add(normalizeKey(row.codigo_cliente));
            }
            agent.totalScores += (row.nota_media || 0);
            agent.auditoriaCount++;
        });

        // Header and Titles
        const generationDate = new Date().toLocaleString('pt-BR');
        const title = "Resumo Loja Perfeita - Notas de Execução";
        const roleStr = isPromoterMode ? 'Promotor' : 'Vendedor';

        doc.setFontSize(18);
        doc.text(title, 14, 22);

        doc.setFontSize(10);
        doc.setTextColor(100);
        doc.text(`Data de Emissão: ${generationDate}`, 14, 30);
        doc.text(`Visualização Ativa: ${roleStr}es`, 14, 36);

        // Get Filters
        let filtersText = '';
        if (isPromoterMode) {
            const coord = document.getElementById('lp-coord-filter-text')?.textContent || 'Todos';
            const cocoord = document.getElementById('lp-cocoord-filter-text')?.textContent || 'Todos';
            const promotor = document.getElementById('lp-promotor-filter-text')?.textContent || 'Todos';
            filtersText = `Filtros Aplicados: Coordenador: ${coord} | Co-Coordenador: ${cocoord} | Promotor: ${promotor}`;
        } else {
            const sup = document.getElementById('lp-supervisor-filter-text')?.textContent || 'Todos';
            const vend = document.getElementById('lp-seller-filter-text')?.textContent || 'Todos';
            filtersText = `Filtros Aplicados: Supervisor: ${sup} | Vendedor: ${vend}`;
        }
        
        const pesquisador = document.getElementById('lp-researcher-filter-text')?.textContent || 'Todos';
        filtersText += ` | Pesquisador: ${pesquisador}`;

        doc.setFontSize(9);
        doc.text(filtersText, 14, 42);

        // Calculate Total Geral de Pesquisas overall and per filial based strictly on the allowedClientCodes
        // Wait, the allowedClientCodes already applies all filters EXCEPT the researcher filter.
        // We also need to compute per-filial breakdown for the top right.

        const configBranches = (window.embeddedData && window.embeddedData.config_city_branches) ? window.embeddedData.config_city_branches : [];
        const uniqueClientsOverallPDF = new Set();
        const filialCounts = new Map(); // branch -> Set of clients

        if (embeddedData.nota_perfeita && lpState.allowedClientCodes) {
            for (let i = 0; i < embeddedData.nota_perfeita.length; i++) {
                const row = embeddedData.nota_perfeita[i];
                const normCode = normalizeKey(row.codigo_cliente);
                if (lpState.allowedClientCodes.has(normCode)) {
                    uniqueClientsOverallPDF.add(normCode);

                    // Since row here is raw data, we need to map city to filial again for the global count
                    let cFilial = 'DESCONHECIDA';
                    // We can look it up efficiently if we have the client obj, but the row has no city.
                    // However, we cached `clientMap` in `updateLpView`? No, it's local.
                    // Let's use the allClientsData or just extract from `data` array if we want exact matching.
                    // Actually, `kpiTotalOverall` should match the KPI in view. It ignores researcher filter.
                    // Let's lookup city from allClientsData.
                }
            }
        }

        // Let's find the filial for all allowed clients
        const allAllowedClients = getHierarchyFilteredClients('lp', allClientsData);
        
        // Keep track of which clients we mapped, to handle orphans safely
        const mappedClients = new Set();
        
        for(let i=0; i<allAllowedClients.length; i++) {
             const c = allAllowedClients[i];
             const code = normalizeKey(c['Código'] || c['codigo_cliente']);
             if (uniqueClientsOverallPDF.has(code)) {
                 mappedClients.add(code);
                 let cFilial = 'DESCONHECIDA';
                 if (c.cidade) {
                     const normCity = normalizeCity(c.cidade);
                     const branchRow = configBranches.find(r => normalizeCity(r.cidade) === normCity);
                     if (branchRow && branchRow.filial) {
                         cFilial = branchRow.filial.trim().toUpperCase();
                     }
                 }
                 if (!filialCounts.has(cFilial)) filialCounts.set(cFilial, new Set());
                 filialCounts.get(cFilial).add(code);
             }
        }
        
        // Assign orphans to DESCONHECIDA
        uniqueClientsOverallPDF.forEach(code => {
            if (!mappedClients.has(code)) {
                if (!filialCounts.has('DESCONHECIDA')) filialCounts.set('DESCONHECIDA', new Set());
                filialCounts.get('DESCONHECIDA').add(code);
            }
        });

        const kpiTotalOverall = uniqueClientsOverallPDF.size;

        // --- Add KPI at Top Right ---
        doc.setFontSize(10);
        doc.setTextColor(0);
        doc.setFont('helvetica', 'bold');
        const kpiText1 = 'Total Geral de Pesquisas:';
        const kpiText2 = `${kpiTotalOverall}`;
        const pageWidth = doc.internal.pageSize.getWidth();
        // Right align bounding box
        doc.text(kpiText1, pageWidth - 14, 22, { align: 'right' });
        doc.setFontSize(14);
        doc.setTextColor(34, 197, 94); // some green
        doc.text(kpiText2, pageWidth - 14, 30, { align: 'right' });

        // Add Breakdown by Filial directly below
        doc.setFontSize(11);
        let currentX = pageWidth - 14;
        const colorMap = {
            '05': [59, 130, 246], // Blue
            '08': [168, 85, 247], // Purple
            'DESCONHECIDA': [156, 163, 175] // Gray
        };

        const sortedFiliais = Array.from(filialCounts.keys()).sort().reverse();
        sortedFiliais.forEach(fKey => {
            const count = filialCounts.get(fKey).size;
            if (count > 0) {
                const fVal = `${count}`;
                const fLabel = `Filial ${fKey}: `;

                doc.setTextColor(...(colorMap[fKey] || [0, 0, 0]));
                doc.text(fVal, currentX, 36, { align: 'right' });
                const valWidth = doc.getTextWidth(fVal);
                currentX -= valWidth + 1;

                doc.setTextColor(139, 0, 0); // Dark red for "Filial X:"
                doc.text(fLabel, currentX, 36, { align: 'right' });
                const labelWidth = doc.getTextWidth(fLabel);
                currentX -= labelWidth + 4;
            }
        });

        // Print Tables per Filial
        let startY = 50;

        // Sort filiais for tables
        const tableFiliais = Array.from(filialMap.keys()).sort();

        if (tableFiliais.length === 0) {
             doc.text("Nenhum dado encontrado para o período ou filtros selecionados..", 14, startY);
        }

        tableFiliais.forEach(fKey => {
            // Check if page break is needed
            if (startY > doc.internal.pageSize.getHeight() - 40) {
                doc.addPage();
                startY = 20;
            }

            const agentMap = filialMap.get(fKey);
            const tableBody = [];
            let totalPesquisas = 0;
            let totalPerfeitas = 0;
            let sumMedias = 0;
            let countMedias = 0;

            agentMap.forEach((agent) => {
                const qtdPesquisas = agent.clients.size;
                const qtdPerfeitas = agent.lojasPerfeitas.size;
                const media = agent.auditoriaCount > 0 ? agent.totalScores / agent.auditoriaCount : 0;

                tableBody.push([
                    agent.code,
                    agent.name,
                    qtdPesquisas,
                    qtdPerfeitas,
                    media.toFixed(1)
                ]);

                totalPesquisas += qtdPesquisas;
                totalPerfeitas += qtdPerfeitas;
                if (qtdPesquisas > 0) {
                    sumMedias += media;
                    countMedias++;
                }
            });

            tableBody.sort((a, b) => parseFloat(b[3]) - parseFloat(a[3]));

            const mediaFilial = countMedias > 0 ? (sumMedias / countMedias) : 0;

            tableBody.push([
                { content: 'TOTAL', colSpan: 2, styles: { halign: 'right', fontStyle: 'bold' } },
                { content: totalPesquisas.toString(), styles: { fontStyle: 'bold', halign: 'center' } },
                { content: totalPerfeitas.toString(), styles: { fontStyle: 'bold', halign: 'center' } },
                { content: mediaFilial.toFixed(1), styles: { fontStyle: 'bold', halign: 'center' } }
            ]);

            doc.setFontSize(12);
            doc.setTextColor(0);
            doc.setFont('helvetica', 'bold');
            doc.text(`Filial: ${fKey}`, 14, startY);

            doc.autoTable({
                startY: startY + 4,
                head: [[
                    `Código (${roleStr})`,
                    `Nome (${roleStr})`,
                    'Qtd. Pesquisas',
                    'Lojas Perfeitas',
                    'Média de Nota'
                ]],
                body: tableBody,
                theme: 'grid',
                headStyles: { fillColor: [30, 41, 59], textColor: 255, fontStyle: 'bold', halign: 'center' },
                styles: { fontSize: 9, cellPadding: 3, textColor: [0, 0, 0] },
                alternateRowStyles: { fillColor: [240, 240, 240] },
                columnStyles: {
                    0: { cellWidth: 35, halign: 'center' },
                    1: { cellWidth: 'auto' },
                    2: { cellWidth: 40, halign: 'center' },
                    3: { cellWidth: 40, halign: 'center' },
                    4: { cellWidth: 40, halign: 'center' }
                }
            });

            startY = doc.lastAutoTable.finalY + 10;
        });

        doc.save(`Loja_Perfeita_Resumo_${isPromoterMode ? 'Promotor' : 'Vendedor'}.pdf`);

    } catch (e) {
        console.error('Error generating PDF:', e);
        if (window.showToast) window.showToast('error', 'Erro ao gerar o PDF.');
    }
}
    async function renderLojaPerfeitaView() {
        // Lazy Load Data
        if (!window.nota_perfeita) {
            const container = document.getElementById('lp-kpis-grid');
            if (container) container.innerHTML = '<div class="col-span-full text-center py-10 text-slate-400">Baixando dados de Loja Perfeita...</div>';

            try {
                const { data, error } = await window.supabaseClient.from('data_nota_perfeita').select('*');
                if (error) throw error;

                if (data && data.length > 0) {
                    data.forEach(row => {
                        if (row.pesquisador) {
                            row.pesquisador = String(row.pesquisador).toUpperCase().replace(/\s+/g, '');
                        }
                    });
                }

                window.nota_perfeita = data || [];

                // Update cache asynchronously
                window.cachedData = window.cachedData || {};
                window.cachedData.nota_perfeita = window.nota_perfeita;
            } catch (e) {
                console.error("Erro ao carregar Loja Perfeita lazy:", e);
                if (container) container.innerHTML = '<div class="col-span-full text-center py-10 text-red-500">Erro ao carregar dados.</div>';
                return;
            }
        }

        // Inject Researcher Filter (New)
        const lpGrid = document.querySelector('#loja-perfeita-view .sticky-filters .grid');
        if (lpGrid && !document.getElementById('lp-researcher-filter-wrapper')) {
            const wrapper = document.createElement('div');
            wrapper.id = 'lp-researcher-filter-wrapper';
            wrapper.className = 'relative z-20'; 
            wrapper.innerHTML = `
                <label class="block mb-2 text-xs font-bold text-slate-500 uppercase">Pesquisador</label>
                <button id="lp-researcher-filter-btn" class="w-full glass-panel text-slate-300 text-sm rounded-lg p-2.5 text-left flex justify-between items-center focus:ring-2 focus:ring-[#FF5E00] hover:bg-slate-750 transition-colors focus-visible:ring-2 focus-visible:ring-[#FF5E00] focus-visible:outline-none focus-visible:ring-offset-2 focus-visible:ring-offset-slate-900">
                    <span id="lp-researcher-filter-text">Todos</span>
                    <svg class="w-4 h-4 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M19 9l-7 7-7-7"></path></svg>
                </button>
                <div id="lp-researcher-filter-dropdown" class="hidden absolute z-30 w-full mt-2 glass-panel rounded-xl shadow-2xl max-h-60 overflow-y-auto custom-scrollbar p-2"></div>
            `;
            // Insert before Client Filter if exists
            const clientWrapper = document.getElementById('lp-codcli-filter-wrapper');
            if (clientWrapper) {
                 lpGrid.insertBefore(wrapper, clientWrapper);
            } else {
                 lpGrid.appendChild(wrapper);
            }
        }

        setupHierarchyFilters('lp', () => handleLpFilterChange({ excludeFilter: 'hierarchy' }));
        setupLpFilialFilterHandlers();
        setupLpSupervisorFilterHandlers();
        setupLpResearcherFilterHandlers();

        // Rede Filters
        const redeGroupContainer = document.getElementById('lp-rede-group-container');
        const comRedeBtn = document.getElementById('lp-com-rede-btn');
        const comRedeBtnText = document.getElementById('lp-com-rede-btn-text');
        const redeDropdown = document.getElementById('lp-rede-filter-dropdown');

        if (redeGroupContainer && !redeGroupContainer._hasListener) {
            redeGroupContainer.addEventListener('click', (e) => {
                const btn = e.target.closest('button');
                if (!btn) return;
                const group = btn.dataset.group;
                lpRedeGroupFilter = group;
                redeGroupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                if (group === 'com_rede') redeDropdown.classList.remove('hidden');
                else redeDropdown.classList.add('hidden');
                handleLpFilterChange();
            });
            redeGroupContainer._hasListener = true;
        }

        if (redeDropdown && !redeDropdown._hasListener) {
            redeDropdown.addEventListener('change', () => handleLpFilterChange());
            redeDropdown._hasListener = true;
        }

        // Client Search
        setupClientTypeahead('lp-codcli-filter', 'lp-codcli-filter-suggestions', (code) => {
            handleLpFilterChange();
        });
        const clientInput = document.getElementById('lp-codcli-filter');
        if (clientInput && !clientInput._hasListener) {
            clientInput.addEventListener('input', (e) => {
                 if (!e.target.value) handleLpFilterChange();
            });
            clientInput._hasListener = true;
        }

        // Clear Btn
        const clearBtn = document.getElementById('clear-lp-filters-btn');
        if(clearBtn && !clearBtn._hasListener) {
            clearBtn.addEventListener('click', () => {
                 resetLpFilters();
            });
            clearBtn._hasListener = true;
        }

        // Pagination
        const prevBtn = document.getElementById('lp-prev-page-btn');
        const nextBtn = document.getElementById('lp-next-page-btn');
        if(prevBtn && !prevBtn._hasListener) {
            prevBtn.addEventListener('click', () => {
                if(lpState.page > 1) {
                    lpState.page--;
                    renderLpTable();
                }
            });
            prevBtn._hasListener = true;
        }
        if(nextBtn && !nextBtn._hasListener) {
            nextBtn.addEventListener('click', () => {
                const max = Math.ceil(lpState.filteredData.length / lpState.limit);
                if(lpState.page < max) {
                    lpState.page++;
                    renderLpTable();
                }
            });
            nextBtn._hasListener = true;
        }

        // Initial Filter Population (Rede)
        updateLpRedeFilter();

        // Initial Render
        updateLpView();
    }

    function updateLpRedeFilter() {
        const clients = getHierarchyFilteredClients('lp', allClientsData);
        const dropdown = document.getElementById('lp-rede-filter-dropdown');
        const btnText = document.getElementById('lp-com-rede-btn-text');
        if(dropdown) {
            selectedLpRedes = updateRedeFilter(dropdown, btnText, selectedLpRedes, clients);
        }
    }

    function handleLpFilterChange(options = {}) {
         if(window.lpUpdateTimeout) clearTimeout(window.lpUpdateTimeout);
         window.lpUpdateTimeout = setTimeout(() => {
             const { excludeFilter } = options;
             if (excludeFilter !== 'researcher') {
                 updateLpResearcherFilter();
             }
             updateLpView();
         }, 10);
    }

    function resetLpFilters() {
        selectedLpRedes = [];
        selectedLpResearchers.clear();
        selectedLpSupervisors.clear();
        selectedLpVendedores.clear();


        const filialInput = document.getElementById('lp-filial-filter');
        if (filialInput) filialInput.value = 'all';
        const filialText = document.getElementById('lp-filial-filter-text');
        if (filialText) filialText.textContent = 'Todas';
        const filialRadios = document.querySelectorAll('input[name="lp-filial"]');
        if (filialRadios) {
            filialRadios.forEach(r => r.checked = r.value === 'all');
        }

        lpRedeGroupFilter = '';
        document.getElementById('lp-codcli-filter').value = '';

        if (hierarchyState['lp']) {
            hierarchyState['lp'].coords.clear();
            hierarchyState['lp'].cocoords.clear();
            hierarchyState['lp'].promotors.clear();
        }

        const groupContainer = document.getElementById('lp-rede-group-container');
        if(groupContainer) {
             groupContainer.querySelectorAll('button').forEach(b => b.classList.remove('active'));
             groupContainer.querySelector('button[data-group=""]').classList.add('active');
        }
        const dd = document.getElementById('lp-rede-filter-dropdown');
        if(dd) dd.classList.add('hidden');
        
        const ddRes = document.getElementById('lp-researcher-filter-dropdown');
        if(ddRes) ddRes.classList.add('hidden');

        setupHierarchyFilters('lp'); // Reset hierarchy & update hierarchy dropdowns
        updateLpRedeFilter();
        updateLpResearcherFilter();
        updateLpSupervisorFilter();
        updateLpVendedorFilter();
        updateLpView();
    }

    function updateLpView() {
        lpRenderId++;
        const currentId = lpRenderId;

        // 1. Get Data
        const rawData = embeddedData.nota_perfeita;
        if (!rawData || !rawData.length) {
            // Empty state
            renderLpKPIs(0, 0, 0, 0);
            lpState.filteredData = [];
            renderLpTable();
            return;
        }

        // 2. Filter Clients Base (Hierarchy + Rede)
        let allowedClients;
        if (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller') {
            allowedClients = [];
            const hasSup = selectedLpSupervisors.size > 0;
            const hasVend = selectedLpVendedores.size > 0;
            const source = allClientsData;
            const len = source.length;
            for(let i=0; i<len; i++) {
                const c = source instanceof ColumnarDataset ? source.get(i) : source[i];
                const rca1 = String(c.rca1 || '').trim();
                const isAmericanas = c.isAmericanas !== undefined ? c.isAmericanas : (c.isAmericanas = (c.razaoSocial || '').toUpperCase().includes('AMERICANAS'));
                // FIX: Match Metas logic: Drop inactive unless Americanas. Keep orphans if no filter.
                if (window.userRole === 'adm' && !isAmericanas && rca1 === '') {
                    if (hasSup || hasVend) {
                        continue;
                    }
                } else if (!window.isActiveClient(c) && !isAmericanas) {
                    continue;
                }
                let keep = true;
                if (hasSup || hasVend) {
                    const details = sellerDetailsMap.get(rca1);
                    if (hasSup) {
                        if (!details || !selectedLpSupervisors.has(details.supervisor)) keep = false;
                    }
                    if (keep && hasVend) {
                        if (!selectedLpVendedores.has(rca1)) keep = false;
                    }
                }
                if (keep) allowedClients.push(c);
            }
        } else {
            allowedClients = getHierarchyFilteredClients('lp', allClientsData);
        }


        // Apply Rede Filter
        const isComRede = lpRedeGroupFilter === 'com_rede';
        const isSemRede = lpRedeGroupFilter === 'sem_rede';
        const redeSet = (isComRede && selectedLpRedes.length > 0) ? new Set(selectedLpRedes) : null;
        const clientSearch = document.getElementById('lp-codcli-filter').value.toLowerCase().trim();

        const filialFilterInput = document.getElementById('lp-filial-filter');
        const selectedFilial = filialFilterInput ? filialFilterInput.value : 'all';

        const allowedClientCodes = new Set();
        const clientMap = new Map(); // Store metadata for table enrichment

        // Build City to Filial Cache
        const configBranches = (window.embeddedData && window.embeddedData.config_city_branches) ? window.embeddedData.config_city_branches : [];

        for(let i=0; i<allowedClients.length; i++) {
            const c = allowedClients[i];

            // Rede Check
            if (isComRede) {
                if (!c.ramo || c.ramo === 'N/A') continue;
                if (redeSet && !redeSet.has(c.ramo)) continue;
            } else if (isSemRede) {
                if (c.ramo && c.ramo !== 'N/A') continue;
            }

            // Filial Check
            let cFilial = 'desconhecida';
            if (c.cidade) {
                const normCity = normalizeCity(c.cidade);
                const branchRow = configBranches.find(r => normalizeCity(r.cidade) === normCity);
                if (branchRow && branchRow.filial) {
                    cFilial = branchRow.filial.trim().toUpperCase();
                }
            }
            c.calculatedFilial = cFilial; // Save for PDF/Table

            if (selectedFilial !== 'all') {
                if (selectedFilial === 'desconhecida' && cFilial !== 'desconhecida') continue;
                if (selectedFilial !== 'desconhecida' && cFilial !== selectedFilial) continue;
            }

            // Search Check
            if (clientSearch) {
                const code = String(c['Código'] || c['codigo_cliente']).toLowerCase();
                const name = (c.nomeCliente || '').toLowerCase();
                if (!code.includes(clientSearch) && !name.includes(clientSearch)) continue;
            }

            const code = normalizeKey(c['Código'] || c['codigo_cliente']);
            allowedClientCodes.add(code);
            clientMap.set(code, c);
        }

        // Identify all existing clients in master DB to distinguish orphans
        const allExistingCodes = new Set();
        const lenMaster = allClientsData.length;
        for(let i=0; i<lenMaster; i++) {
            const c = allClientsData instanceof ColumnarDataset ? allClientsData.get(i) : allClientsData[i];
            allExistingCodes.add(normalizeKey(c['Código'] || c['codigo_cliente']));
        }

        // We will dynamically add true orphans to allowedClientCodes so PDF logic matches
        const orphansToAdd = new Set();

        lpState.allowedClientCodes = allowedClientCodes;

        // 3. Filter Data
        const filtered = [];
        for (let i = 0; i < rawData.length; i++) {
            const row = rawData[i];
            const normCode = normalizeKey(row.codigo_cliente);
            
            let isAllowed = allowedClientCodes.has(normCode) || orphansToAdd.has(normCode);
            
            if (!isAllowed) {
                // If it exists in master DB, it was filtered out by Hierarchy or Client Filters -> DROP
                if (allExistingCodes.has(normCode)) {
                    continue;
                }
                
                // It's a true orphan (doesn't exist in master DB). Apply active UI filters manually:
                let keepOrphan = true;
                
                // 1. Rede
                if (isComRede) keepOrphan = false; // Orphans have no Rede
                
                // 2. Filial
                if (selectedFilial !== 'all' && selectedFilial !== 'desconhecida') keepOrphan = false; // Orphans are 'desconhecida'
                
                // 3. Search
                if (clientSearch && !normCode.includes(clientSearch)) keepOrphan = false;
                
                // 4. Seller Hierarchy mode
                if (typeof adminViewMode !== 'undefined' && adminViewMode === 'seller') {
                    if (selectedLpSupervisors.size > 0 || selectedLpVendedores.size > 0) keepOrphan = false;
                }
                
                if (!keepOrphan) continue;
                
                // Orphan passed filters, add it
                isAllowed = true;
                orphansToAdd.add(normCode);
            }

            // Researcher Filter
            if (selectedLpResearchers.size > 0) {
                if (!row.pesquisador || !selectedLpResearchers.has(row.pesquisador.trim())) continue;
            }

            const c = clientMap.get(normCode);
            filtered.push({
                 ...row,
                 clientName: c ? (c.nomeCliente || c.fantasia) : 'Desconhecido',
                 city: c ? (c.cidade || 'N/A') : 'N/A',
                 filial: c ? c.calculatedFilial : 'desconhecida'
            });
        }
        
        // Merge allowed orphans into allowedClientCodes so KPIs and PDF logic are consistent
        orphansToAdd.forEach(code => allowedClientCodes.add(code));

        // 4. Update KPIs
        let totalScore = 0;
        let totalAudits = 0;
        let totalPerfectAudits = 0;
        const clientScoresMap = new Map();
        const uniqueClientsAudited = new Set();

        filtered.forEach(item => {
            let score = 0;
            let points = Number(item.pontos_realizados || item.pontos || item.nota || 0);
            let maxPoints = Number(item.pontos_maximos || item.maximo_pontos || 0);
            
            if (maxPoints > 0) {
                score = (points / maxPoints) * 100;
            } else if (item.nota_media !== undefined && item.nota_media !== null) {
                score = Number(item.nota_media);
            } else {
                score = points;
            }

            totalScore += score; 
            totalAudits += item.auditorias;
            totalPerfectAudits += item.auditorias_perfeitas;
            
            let uniqueKey = null;
            const lookupCode2 = normalizeKey(item.codigo_cliente);
            const clientObj2 = clientMap.get(lookupCode2);
            
            let targetCnpj2 = item.cnpj || (clientObj2 && clientObj2.cnpj);
            let targetCnpjCpf2 = item.cnpj_cpf || (clientObj2 && clientObj2.cnpj_cpf);
            
            if (targetCnpj2) {
                uniqueKey = String(targetCnpj2).replace(/\D/g, '');
            } else if (targetCnpjCpf2) {
                uniqueKey = String(targetCnpjCpf2).replace(/\D/g, '');
            }
            if (!uniqueKey && item.codigo_cliente) {
                uniqueKey = normalizeKey(item.codigo_cliente);
            }

            if (uniqueKey) {
                uniqueClientsAudited.add(uniqueKey);
                
                let stats = clientScoresMap.get(uniqueKey);
                if (!stats) {
                    stats = { totalScore: 0, count: 0 };
                    clientScoresMap.set(uniqueKey, stats);
                }
                stats.totalScore += score;
                stats.count += 1;
            }
        });

        let perfectStoresCount = 0;
        for (const stats of clientScoresMap.values()) {
            if ((stats.totalScore / stats.count) >= 80) {
                perfectStoresCount++;
            }
        }

        const avgScore = filtered.length > 0 ? (totalScore / filtered.length) : 0;
        // Perfect Store %: (Perfect Stores Count / Total Distinct Audits) * 100
        const perfectPct = uniqueClientsAudited.size > 0 ? (perfectStoresCount / uniqueClientsAudited.size) * 100 : 0;

        // Total Auditorias now uses distinct client count as requested
        const kpiTotalAudits = uniqueClientsAudited.size;

        renderLpKPIs(avgScore, kpiTotalAudits, perfectPct, perfectStoresCount);

        // 5. Update Table
        // Sort by Score Descending
        filtered.sort((a,b) => b.nota_media - a.nota_media);

        lpState.filteredData = filtered;
        lpState.page = 1;
        renderLpTable();
    }

    function renderLpKPIs(avg, audits, perfectPct, perfectCount) {
        document.getElementById('lp-kpi-avg-score').textContent = avg.toFixed(1);
        document.getElementById('lp-kpi-total-audits').textContent = audits;
        document.getElementById('lp-kpi-perfect-stores').textContent = perfectPct.toFixed(1) + '%';
        document.getElementById('lp-kpi-perfect-count').textContent = `${perfectCount} Auditorias`;
    }

    function renderLpTable() {
        const tbody = document.getElementById('lp-table-body');
        if(!tbody) return;

        const { page, limit, filteredData } = lpState;
        const total = filteredData.length;
        const start = (page - 1) * limit;
        const end = start + limit;
        const subset = filteredData.slice(start, end);
        const totalPages = Math.ceil(total / limit) || 1;

        if (total === 0) {
            tbody.innerHTML = '<tr><td colspan="5" class="text-center py-8 text-slate-500">Nenhum dado encontrado para o período ou filtros selecionados..</td></tr>';
            document.getElementById('lp-page-info-text').textContent = '0 de 0';
            return;
        }

        tbody.innerHTML = subset.map(t => {
            let colorStyle;
            if (t.nota_media < 50) colorStyle = 'color: #ef4444 !important;'; 
            else if (t.nota_media < 80) colorStyle = 'color: #eab308 !important;';
            else colorStyle = 'color: #22c55e !important;';
            
            // Resolve Researcher Display
            let resDisplay = t.pesquisador;
            let resSub = t.pesquisador;

            const rawPesquisador = (t.pesquisador || '').trim();
            const resKey = window.normalizeResearcherCode(rawPesquisador);
            const upperResKey = rawPesquisador.toUpperCase();

            // 1. Try to resolve using optimizedData.promotorMap directly (Best match for Promotors)
            if (typeof optimizedData !== 'undefined' && optimizedData.promotorMap && optimizedData.promotorMap.has(upperResKey)) {
                let pName = optimizedData.promotorMap.get(upperResKey);
                pName = pName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();
                resDisplay = pName || rawPesquisador;
                resSub = rawPesquisador;
            }
            // 2. Fallback to lpResearcherMap
            else if (lpResearcherMap.has(resKey)) {
                const info = lpResearcherMap.get(resKey);
                let rawName = info.sellerName || info.sellerCode;
                // remove prefixes just like in filter
                rawName = rawName.replace(/^(PROMOT\.|RCA\s*|SUPERV\.|LIDER\s*)/i, '').trim();

                if (rawName && rawName !== info.sellerCode) {
                    // Try to get first and second name for better display instead of just first name
                    // if it's too long, but if it's like "ARIANA", it works.
                    // The filter uses the full name but formatted. Let's match exactly what we did in the filter.
                    resDisplay = rawName;
                } else {
                    resDisplay = info.sellerCode;
                }
                resSub = info.sellerCode;
            }
            // 3. Fallback to raw value
            else {
                resDisplay = rawPesquisador.toUpperCase();
                resSub = rawPesquisador.toUpperCase();
            }

            const researcherHtml = `
                <div class="flex flex-col justify-center">
                    <span class="text-xs text-white font-bold leading-tight">${window.escapeHtml(resDisplay)}</span>
                    <span class="text-[9px] text-slate-500 leading-tight">${window.escapeHtml(resSub)}</span>
                </div>
            `;

            return `
                <tr class="hover:bg-slate-700/50 border-b border-white/5 transition-colors flex md:table-row justify-between items-center">
                    <td class="px-4 py-3 font-mono text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(t.codigo_cliente)}</td>
                    <td class="px-4 py-3 text-sm text-white font-medium truncate max-w-[200px] border-none" title="${window.escapeHtml(t.clientName)}">${window.escapeHtml(t.clientName)}</td>
                    <td class="px-4 py-3 hidden md:table-cell">${researcherHtml}</td>
                    <td class="px-4 py-3 text-xs text-slate-400 hidden md:table-cell">${window.escapeHtml(t.city)}</td>
                    <td class="px-4 py-3 text-center font-bold border-none" style="${colorStyle}">${t.nota_media.toFixed(1)}</td>
                </tr>
            `;
        }).join('');

        // Pagination UI
        document.getElementById('lp-prev-page-btn').disabled = page === 1;
        document.getElementById('lp-next-page-btn').disabled = page >= totalPages;
        document.getElementById('lp-page-info-text').textContent = `${start + 1}-${Math.min(end, total)} de ${total}`;
    }

